const N5_EN = {"n5-1":{"cat":"Basic Sentence Patterns","ex":"Affirmative uses 「です」, negative uses 「じゃありません」. Plain form: だ／じゃない.","eg":["Mr. Murakami is a doctor.","Ms. Kono is not a housewife."],"t":"～です・～じゃありません (noun)","p":"noun ＋ です／じゃありません"},"n5-2":{"cat":"Basic Sentence Patterns","ex":"The polite present tense. Used with elders and strangers.","eg":["Next week, Mr. Hayashi will go to Kyoto on a business trip.","Professor Tamura does not drink alcohol."],"t":"～ます・～ません","p":"verb masu-form ＋ ます／ません"},"n5-3":{"cat":"Basic Sentence Patterns","ex":"The polite form of na-adjectives: stem + 「です」 (affirmative) / stem + 「じゃありません」 (negative). Add 「な」 when the adjective modifies a noun directly (e.g. 「静かな店」).","eg":["This coffee shop is quiet.","The new store manager isn't kind."],"t":"～です・～じゃありません (na-adjective)","p":"na-adjective stem ＋ です／じゃありません"},"n5-4":{"cat":"Basic Sentence Patterns","ex":"The present tense of i-adjectives: i-adjective + 「です」 (affirmative) / drop 「い」 and add 「くないです」 (negative). The negative of 「いい」 is irregular: 「よくないです」.","eg":["Winters in Sapporo are cold.","This novel isn't interesting."],"t":"～いです・～くないです","p":"i-adjective ＋ です／い→くないです"},"n5-5":{"cat":"Basic Sentence Patterns","ex":"The past tense of nouns: noun + 「でした」 (affirmative) / noun + 「じゃありませんでした」 (negative).","eg":["Last Monday was a national holiday.","The old school building wasn't a library back then."],"t":"～でした (noun past)","p":"noun ＋ でした／じゃありませんでした"},"n5-6":{"cat":"Basic Sentence Patterns","ex":"The polite past tense of verbs.","eg":["Last month, I went to Sapporo.","Last night, I didn't eat dinner."],"t":"～ました・～ませんでした","p":"verb masu-form ＋ ました／ませんでした"},"n5-7":{"cat":"Basic Sentence Patterns","ex":"The past tense of na-adjectives, formed the same way as nouns: stem + 「でした」 (affirmative) / stem + 「じゃありませんでした」 (negative).","eg":["The interview was tough.","Kobe wasn't lively in the old days."],"t":"～でした (na-adjective past)","p":"na-adjective stem ＋ でした／じゃありませんでした"},"n5-8":{"cat":"Basic Sentence Patterns","ex":"Drop the 「い」 and add 「かったです」. 「いい」 becomes 「よかったです」.","eg":["Okinawa was hot last week.","The summer festival was great."],"t":"～かったです (i-adjective past)","p":"i-adjective い→かったです／くなかったです"},"n5-9":{"cat":"Basic Sentence Patterns","ex":"A soft, considerate invitation: \"Won't you ~?\" / \"Would you like to ~?\" Unlike 「ましょう」, which assumes the listener will join in, 「ませんか」 asks and leaves them free to decline, so it feels more polite.","eg":["Would you like to go hiking this coming Sunday?","How about a coffee or something?"],"t":"～ませんか","p":"verb masu-form ＋ ませんか"},"n5-10":{"cat":"Basic Sentence Patterns","ex":"Indicates the result of a natural change (something becoming a certain way): i-adjective → drop 「い」 + 「くなります」; na-adjective / noun → 「になります」.","eg":["When October comes, it gets cooler.","I got good at the piano."],"t":"～くなります・～になります","p":"i-adjective い→くなります／na-adjective・noun→になります"},"n5-11":{"cat":"Basic Sentence Patterns","ex":"Indicates a deliberate change made by someone (making something a certain way): i-adjective → drop 「い」 + 「くします」; na-adjective / noun → 「にします」.","eg":["I'll cut my hair short.","I'll tidy up my desk."],"t":"～くします・～にします","p":"i-adjective い→くします／na-adjective・noun→にします"},"n5-12":{"cat":"Basic Sentence Patterns","ex":"A suggestion meaning \"let's do it together.\"","eg":["Let's go into that cafe.","Let's wait in front of the station."],"t":"～ましょう","p":"verb masu-form ＋ ましょう"},"n5-13":{"cat":"Basic Sentence Patterns","ex":"Polite form is used in formal situations; plain form is used with friends and family.","eg":["It's sunny on the weekend.","I'm reading a book."],"t":"Polite form and plain form","p":"polite form (です・ます) / plain form (だ・dictionary form, etc.)"},"n5-14":{"cat":"Basic Sentence Patterns","ex":"The two negative forms are interchangeable. 「ません」 is more formal, 「ないです」 is more colloquial.","eg":["(I) don't eat.","(It's) not cold."],"t":"Polite negative expression","p":"～ません ＝ ～ないです"},"n5-15":{"cat":"Particles","ex":"Marks the topic of the sentence and is read \"wa.\" It is not necessarily the same as the grammatical subject.","eg":["Mr. Ito is an architect.","As for that cake, my older sister baked it."],"n":"「は」 marks old information (the topic), while 「が」 marks new information (the focus).","t":"Particle 「は」 (topic)","p":"noun ＋ は"},"n5-16":{"cat":"Particles","ex":"Means \"also/too.\" It replaces the particles 「は」, 「が」, and 「を」, but attaches after other particles such as 「に」 or 「で」 (e.g. 「ここにも」 \"here too\").","eg":["Mr. Hayashi is also a lawyer.","I like both bread and cake."],"t":"Particle 「も」","p":"noun ＋ も"},"n5-17":{"cat":"Particles","ex":"Indicates possession or belonging. Similar to the English \"'s\" or \"of.\"","eg":["My younger brother's car.","A math textbook."],"t":"Particle 「の」 (possessive)","p":"noun A ＋ の ＋ noun B"},"n5-18":{"cat":"Particles","ex":"Adding \"か\" at the end of a sentence turns it into a question.","eg":["What is that?","Is Kobayashi a doctor?"],"t":"Particle 「か」 (question)","p":"end of sentence ＋ か"},"n5-19":{"cat":"Particles","ex":"Marks a specific point in time. Relative time expressions (今日 \"today,\" etc.) do not take に.","eg":["I take a walk at 6 in the morning.","There's a welcome party on Friday."],"t":"Particle 「に」 (point in time)","p":"time noun ＋ に"},"n5-20":{"cat":"Particles","ex":"Indicates the direction of movement; pronounced \"e.\" Often interchangeable with 「に」, though 「へ」 emphasizes the direction of movement while 「に」 emphasizes the specific destination.","eg":["I'm traveling to Okinawa.","I'm going back to my hometown."],"t":"Particle 「へ」 (direction)","p":"place ＋ へ"},"n5-21":{"cat":"Particles","ex":"Indicates the means of transportation. For going on foot, use 歩いて.","eg":["I'll take the Shinkansen to Sendai.","I came by taxi."],"t":"Particle 「で」 (means of transport)","p":"transport ＋ で"},"n5-22":{"cat":"Particles","ex":"Indicates the person you do something together with.","eg":["I eat lunch with my colleagues.","Who are you working on that project with?"],"t":"Particle 「と」 (companion)","p":"person ＋ と (一緒に)"},"n5-23":{"cat":"Particles","ex":"Marks the object of an action; pronounced \"o.\"","eg":["I hang out the laundry.","I'm learning French."],"t":"Particle 「を」 (object)","p":"noun ＋ を ＋ transitive verb"},"n5-24":{"cat":"Particles","ex":"Indicates the place where an action takes place. Use に for existence, で for actions.","eg":["I work at a cafe.","I took photos at the beach."],"t":"Particle 「で」 (location of action)","p":"place ＋ で ＋ verb"},"n5-25":{"cat":"Particles","ex":"Indicates a starting point in time or space. Often paired with まで (\"until/to\").","eg":["We're open from 10 a.m. to 6 p.m.","From Fukuoka to Sapporo is two and a half hours by plane."],"t":"Particle 「から」 (starting point)","p":"noun ＋ から"},"n5-26":{"cat":"Particles","ex":"Indicates an end point or limit; \"up to / until ~.\"","eg":["We'll be in the meeting until 5 in the evening.","I'll walk as far as the convenience store."],"t":"Particle 「まで」 (ending point)","p":"noun ＋ まで"},"n5-27":{"cat":"Particles","ex":"Lists items exhaustively; \"A and B\" (a complete list).","eg":["I brought my keys and wallet.","I bought bread and milk."],"t":"Particle 「と」 (listing)","p":"noun A ＋ と ＋ noun B"},"n5-28":{"cat":"Particles","ex":"Lists items non-exhaustively, implying there are others; \"~ and ~ (among other things).\"","eg":["I enjoy karaoke, bowling, and the like.","Bowls, plates, and so on are lined up."],"t":"Particle 「や」 (listing - partial)","p":"noun A ＋ や ＋ noun B (＋ など)"},"n5-29":{"cat":"Particles","ex":"Indicates the tool or means used to do something.","eg":["I drink soup with a spoon.","I send emails in English."],"t":"Particle 「で」 (means/tool)","p":"tool ＋ で"},"n5-30":{"cat":"Particles","ex":"Indicates the recipient or target of an action.","eg":["I give flowers to my mother.","I consult with my boss."],"t":"Particle 「に」 (target of action)","p":"person ＋ に ＋ verb"},"n5-31":{"cat":"Particles","ex":"Indicates a reason or cause; \"A, so B\" (\"B because A\").","eg":["I have a fever, so I'm leaving early.","It's raining, so I won't go out."],"t":"Particle 「から」 (cause/reason)","p":"plain form／polite form ＋ から"},"n5-32":{"cat":"Particles","ex":"Used with expressions of ability and likes/dislikes; the object takes 「が」 (not 「を」).","eg":["I can understand Korean.","I like chocolate."],"t":"Particle 「が」 (ability/likes-dislikes)","p":"noun ＋ が ＋ わかります／好きです, etc."},"n5-33":{"cat":"Particles","ex":"Indicates the location where something exists.","eg":["There are dishes in the cupboard.","There are children in the park."],"t":"Particle 「に」 (location of existence)","p":"place ＋ に ＋ あります／います"},"n5-34":{"cat":"Particles","ex":"Marks the subject. Used for new information, answers to question words, and so on.","eg":["Who painted this picture?","It's snowing."],"t":"Particle 「が」 (subject)","p":"noun ＋ が"},"n5-35":{"cat":"Particles","ex":"Contrastive/adversative connector. \"Although A, B\" / \"A, but B.\"","eg":["This camera is expensive, but the image quality is good.","I'd like to join, but the timing is inconvenient."],"t":"Particle 「が」 (contrast)","p":"sentence A ＋ が ＋ sentence B"},"n5-36":{"cat":"Particles","ex":"A colloquial adversative or lead-in connector. More casual than \"が\".","eg":["It's small, but it's easy to use.","There's a favor I'd like to ask you..."],"t":"Particle 「けど」","p":"sentence A ＋ けど ＋ sentence B"},"n5-37":{"cat":"Particles","ex":"Indicates the purpose of movement (going/coming somewhere in order to do something).","eg":["I'm going (out) to buy souvenirs.","I came to deliver the documents."],"t":"Particle 「に」 (purpose)","p":"verb masu-form (drop ます) ＋ に ＋ 行きます, etc."},"n5-38":{"cat":"Particles","ex":"\"だけ\" is neutral (\"only\"); \"しか + negative\" carries a sense of regret or insufficiency (\"only... / nothing but\").","eg":["I'll order only a salad.","There are only 10 minutes left (not enough)."],"t":"Limiting particles 「だけ」「しか」","p":"だけ (neutral limitation) ／ しか ＋ negative (sense of insufficiency)"},"n5-39":{"cat":"Particles","ex":"\"ね\" seeks agreement or shared feeling; \"よ\" tells or emphasizes new information to the listener.","eg":["The scenery is beautiful, isn't it?","This TV program is interesting, you know."],"t":"Sentence-final particles 「ね」「よ」","p":"end of sentence ＋ ね (confirmation/empathy) ／ よ (informing/emphasis)"},"n5-40":{"cat":"Particles","ex":"A summary of more advanced uses of various particles: を (point of separation/leaving, or passing through), に (frequency/contact/change), で (domain of comparison/scope), は (contrast), か (choice).","eg":["I will graduate from high school. (separation / leaving)","I go to the movie theater twice a month. (frequency)","I'm the youngest on the team. (domain of comparison)","I like sushi, but I'm not fond of sashimi. (contrast)","Coffee or tea, which would you like? (choice)"],"t":"Other particles summary","p":"を (leaving/passing through)・に (frequency/contact/change)・で (unit/scope)・は (contrast)・か (choice)"},"n5-41":{"cat":"Verb Conjugation","ex":"The most basic polite form. Godan verbs: shift the final -u sound to the -i sound + ます. Ichidan verbs: drop る + ます. Irregular: する→します, 来る→来ます.","eg":["nomu → nomimasu: drink (godan)","kiru → kimasu: wear (ichidan)"],"t":"Verb masu-form","p":"godan: u-row→i-row ＋ ます／ichidan: drop る ＋ ます"},"n5-42":{"cat":"Verb Conjugation","ex":"The most important conjugation, used for requests (〜てください), linking/sequencing actions, and the progressive/state form (〜ている). For godan verbs (sound changes): く→いて, ぐ→いで, す→して, む/ぶ/ぬ→んで, う/つ/る→って. For ichidan verbs: drop る + て (e.g., 見る→見て). Exception: 行く→行って.","eg":["hanasu → hanashite (speak), isogu → isoide (hurry)","yasumu → yasunde (rest), tsukau → tsukatte (use)"],"t":"Te-form","p":"godan sound change ＋ て／ichidan: drop る ＋ て"},"n5-43":{"cat":"Verb Conjugation","ex":"Dictionary form = plain-style affirmative. Nai form = plain-style negative. To form the nai form: godan verbs change the final -u sound to the -a sound + ない (and う→わない, e.g., 買う→買わない); ichidan verbs drop る + ない (e.g., 起きる→起きない).","eg":["utaimasu → utau / utawanai: sing / don't sing","okimasu → okiru / okinai: get up / don't get up"],"t":"Dictionary form and nai-form","p":"dictionary form: plain form (ends in u-row) ／ nai-form: a-row ＋ ない"},"n5-44":{"cat":"Verb Conjugation","ex":"Past tense, plain style. The た form is built exactly like the て form, replacing て with た (and で with だ): for godan verbs use the sound changes (e.g., 話す→話した, 急ぐ→急いだ); for ichidan verbs drop る + た (e.g., 見る→見た). The negative past (nakatta form) changes ない→なかった.","eg":["hashiru → hashitta (ran), miru → mita (saw)","nomanai → nomanakatta: didn't drink"],"t":"Ta-form and nakatta-form","p":"ta-form = て→た (で→だ) ／ nakatta-form = ない→なかった"},"n5-45":{"cat":"Verb Conjugation","ex":"The four plain forms: dictionary form / nai form / ta form / nakatta form. For i-adjectives: い / くない / かった / くなかった (e.g., 美しい / 美しくない / 美しかった / 美しくなかった). For na-adjectives and nouns: だ / じゃない / だった / じゃなかった.","eg":["kau / kawanai / katta / kawanakatta: the four verb forms","taisetsu da / ja nai / datta / ja nakatta: the four na-adjective forms (\"important\")"],"t":"Plain form summary","p":"verb・i-adjective・na-adjective・noun: 4 conjugations each"},"n5-46":{"cat":"Adjectives & Modification","ex":"An adjective placed before a noun to modify it. I-adjectives attach directly; na-adjectives add な.","eg":["A little puppy.","A quiet garden."],"t":"Adjectives modifying nouns","p":"i-adjective ＋ noun／na-adjective ＋ な ＋ noun"},"n5-47":{"cat":"Adjectives & Modification","ex":"Using an adjective adverbially to modify a verb. I-adjectives: い→く. Na-adjectives: replace な with に (e.g., 静かな → 静かに).","eg":["To walk quietly.","To dance skillfully."],"t":"Adverbial use of adjectives","p":"i-adjective→く ＋ verb／na-adjective→に ＋ verb"},"n5-48":{"cat":"Adjectives & Modification","ex":"Using a clause to modify a noun, similar to \"the ○○ that...\".","eg":["The book I borrowed last week.","The school my younger brother attends."],"t":"Noun-modifying clauses","p":"plain form ＋ noun"},"n5-49":{"cat":"Adjectives & Modification","ex":"\"の\" nominalizes a verb phrase (turns it into a noun).","eg":["Taking photos is fun.","I like reading novels."],"t":"Formal noun 「の」","p":"verb plain form ＋の＋は／が／を"},"n5-50":{"cat":"Existence & Giving/Receiving","ex":"あります for inanimate things; います for living beings.","eg":["There are scissors in the drawer.","There are students in the classroom."],"t":"Existence expression","p":"place に＋thing が＋あります／います"},"n5-51":{"cat":"Existence & Giving/Receiving","ex":"The three giving/receiving verbs: あげます (I/someone give to others, outward), もらいます (I receive), くれます (someone gives to me or my in-group, inward). やります is a downward variant of あげる, used for giving to those below oneself (e.g., plants, animals).","eg":["I give a souvenir to my colleague.","My older sister gave me a magazine."],"t":"Giving/receiving verbs","p":"あげます (give to someone)／もらいます (receive)／くれます (give to me)"},"n5-52":{"cat":"Te-form Uses","ex":"Three uses: (1) an action in progress, (2) a resulting state, (3) a habitual action.","eg":["I'm doing the laundry right now. (in progress)","I live in Kyoto. (state)"],"t":"～ています","p":"verb te-form ＋います"},"n5-53":{"cat":"Te-form Uses","ex":"The te-form links clauses to show parallel description, sequence of actions, cause, or an accompanying circumstance.","eg":["I get up in the morning, brush my teeth, and head out. (sequence)","I was hungry, so I ate something. (cause)"],"t":"Connective use of te-form","p":"te-form connects multiple actions or states"},"n5-54":{"cat":"Te-form Uses","ex":"Three patterns showing the order of actions: てから (after finishing) / た-form + あとで (after) / dictionary-form + まえに (before).","eg":["I go to bed after brushing my teeth.","I watch the news before going to work."],"t":"～てから・～あとで・～まえに","p":"てから (after doing)／ta-form あとで (after)／dictionary form まえに (before)"},"n5-55":{"cat":"Te-form Uses","ex":"\"Please do ~\" (te-form + ください) and \"Please don't do ~\" (ないで + ください).","eg":["Please sign this document.","Please don't smoke here."],"t":"～てください・～ないでください","p":"te-form ＋ください／ないで＋ください"},"n5-56":{"cat":"Te-form Uses","ex":"Lists representative actions or states, implying there are others besides the ones mentioned.","eg":["I do things like take walks and go to cafés.","The temperature is sometimes high, sometimes low."],"t":"～たり～たりします","p":"verb ta-form ＋り…＋します"},"n5-57":{"cat":"Expressions & Patterns","ex":"「欲しい」expresses wanting an object; 「たい」expresses wanting to do an action. Both are used only for the first person.","eg":["I want a big bookshelf.","I want to soak in a hot spring."],"t":"～が欲しいです・～たいです","p":"noun ＋が欲しい／masu-form (drop ます) ＋たい"},"n5-58":{"cat":"Expressions & Patterns","ex":"Doing two things at the same time. The main action comes in the second (following) clause.","eg":["I clean while listening to the radio.","Don't talk on the phone while driving."],"t":"～ながら","p":"masu-form (drop ます) ＋ながら＋verb"},"n5-59":{"cat":"Expressions & Patterns","ex":"\"When ~.\" A な-adjective takes な and a noun takes の before とき.","eg":["When I'm busy, I eat out.","When I went to Kyoto, I visited some temples."],"t":"～とき","p":"plain form ＋とき"},"n5-60":{"cat":"Expressions & Patterns","ex":"Expresses a guess (falling intonation) or seeks confirmation (rising intonation).","eg":["It will probably be sunny this weekend.","That movie is really moving, isn't it?"],"t":"～でしょう","p":"plain form ＋でしょう"},"n5-61":{"cat":"Expressions & Patterns","ex":"Answers the question 「どうして」(why), emphasizing the reason.","eg":["— Because the bus got stuck in traffic.","— Because I like Japanese culture."],"t":"～からです","p":"plain form ＋からです"},"n5-62":{"cat":"Expressions & Patterns","ex":"Intransitive verbs (with が): something happens on its own / Transitive verbs (with を): someone does it deliberately. Example: 窓が閉まる (intransitive) / 窓を閉める (transitive).","eg":["The window closes. (intransitive)","I close the window. (transitive)"],"t":"Intransitive・transitive verbs","p":"intransitive (が): occurs on its own／transitive (を): deliberate action"},"n5-63":{"cat":"Vocabulary & Others","ex":"Common question words. Question word + も + negative = total negation; question word + か = something indefinite.","eg":["I didn't drink anything.","I want to go somewhere quiet."],"t":"Question words","p":"何・誰・どこ・いつ・どれ・いくら・どう"},"n5-64":{"cat":"Vocabulary & Others","ex":"こ (near the speaker) / そ (near the listener) / あ (far from both) / ど (question). これ/それ/あれ/どれ, ここ/そこ/あそこ/どこ.","eg":["Is this your umbrella?","The reception desk is over there."],"t":"Demonstratives (こそあど)","p":"こ (near speaker)・そ (near listener)・あ (far)・ど (question)"},"n5-65":{"cat":"Vocabulary & Others","ex":"Different objects take different counters: ～つ, ～人 (people), ～本 (long objects), ～枚 (flat objects), etc. くらい means \"about/approximately.\"","eg":["Five stamps, please.","It takes about an hour."],"t":"Counters・time expressions","p":"～つ・～人・～本・～枚 etc. counters"},"n5-66":{"cat":"Vocabulary & Others","ex":"Adverbs. Degree/quantity: とても (very), たくさん (a lot). Frequency, from most to least: いつも (always) > よく (often) > ときどき (sometimes) > たまに (occasionally) > あまり (not much) > 全然 (not at all). あまり and 全然 pair with a negative.","eg":["It was very fun.","I don't watch much TV."],"t":"Adverbs","p":"とても・たくさん・よく・あまり (＋negative)・全然 (＋negative)"},"n5-67":{"cat":"Vocabulary & Others","ex":"Conjunctions such as そして (and), でも (but), だから (so) link sentences; interjections include はい (yes) and あのう (um). Adverbs of manner (ゆっくり slowly, はっきり clearly) and mimetic/onomatopoeic words are a distinctive feature of Japanese.","eg":["I want to buy it. But it's over budget.","Please read slowly."],"t":"Conjunctions・interjections・onomatopoeia","p":"そして・でも・だから (conjunctions)／はい・あのう (interjections)"},"n5-68":{"cat":"Vocabulary & Others","ex":"\"B called/named A\" (noun A + という + noun B). Used to introduce a name or to quote.","eg":["A drama called \"Tokyo Love Story.\"","Someone named Murata contacted me."],"t":"～という","p":"noun A ＋という＋noun B"}};
const N4_EN = {"n4-1":{"cat":"Expressions & Sentence Patterns","ex":"Indicates completing something by a certain deadline. Compare: 「まで」= continuously up until a point (duration), while 「までに」= by/before a deadline (a one-time action must be done at some point before that time).","eg":["Please submit the proposal by next Friday.","I'll be back at the dorm by 11 p.m."],"t":"～までに (deadline)","p":"time ＋までに"},"n4-2":{"cat":"Expressions & Sentence Patterns","ex":"Expresses a planned intention or decision. Use the dictionary form for what you intend to do, and the ない-form for what you intend not to do.","eg":["I'm planning to travel around Hokkaido during summer vacation.","From now on, I intend to cut back on sweets."],"t":"～つもりです (intention)","p":"dictionary form／nai-form ＋つもりです"},"n4-3":{"cat":"Conjecture & Appearance","ex":"Means \"maybe / might / possibly.\" Expresses an uncertain guess about something. The plain form attaches directly (drop 「だ」 for な-adjectives and nouns).","eg":["The wind might be strong on Saturday.","Suzuki might not be able to attend the meeting."],"t":"～かもしれません","p":"plain form ＋かもしれません"},"n4-4":{"cat":"Comparison","ex":"Means \"A is more ... than B.\" A is the topic being described, and B is the standard it is compared against.","eg":["Nagoya has a higher temperature than Sapporo.","The subway is more punctual than the bus."],"t":"～は...より (comparison)","p":"A は B より＋adjective"},"n4-5":{"cat":"Expressions & Sentence Patterns","ex":"「～やすい」means \"easy to do ~,\" and 「～にくい」means \"hard/difficult to do ~.\" Attach to the verb stem (ます-form minus ます). The whole thing conjugates like an い-adjective.","eg":["This pen is easy to write with.","The new store manager's name is hard to remember."],"t":"～やすい・～にくい","p":"masu-form (drop ます) ＋やすい／にくい"},"n4-6":{"cat":"Expressions & Sentence Patterns","ex":"Means \"the way/method of doing ~\" or \"how to do ~.\" Attach 「方（かた）」 to the verb stem (ます-form minus ます).","eg":["Please teach me how to fill out this document.","I don't know how to use the dishwasher."],"t":"～方 (method)","p":"masu-form (drop ます) ＋方 (かた)"},"n4-7":{"cat":"Conjunctions & Cause","ex":"Means \"because ~.\" More polite, softer, and more objective than 「から」. Attaches to the plain form; for な-adjectives and nouns, use 「な＋ので」.","eg":["My back hurts, so I'm going to leave early.","It's a national holiday, so the post office is closed."],"t":"Particle「ので」(cause)","p":"plain form ＋ので (na-adjective/noun: な＋ので)"},"n4-8":{"cat":"Conjunctions & Cause","ex":"Means \"even though ~ / despite ~,\" with a nuance of dissatisfaction, surprise, or regret at the unexpected result. Attaches to the plain form; for な-adjectives and nouns, use 「な＋のに」.","eg":["Even though I looked up the route beforehand, I still got lost.","Even though it's brand new, it's already broken."],"t":"Particle「のに」(contrast)","p":"plain form ＋のに (na-adjective/noun: な＋のに)"},"n4-9":{"cat":"Expressions & Sentence Patterns","ex":"Expresses ability or possibility (\"can do ~\"). Equivalent in meaning to the potential form of the verb. Attach 「ことができます」 to the dictionary form.","eg":["I can play the piano.","You can use Wi-Fi at this library."],"t":"～ことができます","p":"dictionary form ＋ことができます"},"n4-10":{"cat":"Expressions & Sentence Patterns","ex":"Means \"have done ~ before,\" expressing a past experience. Attach 「ことがあります」 to the た-form. The negative 「ことがありません」 means \"have never done ~.\"","eg":["I've encountered deer at Nara Park before.","I've never eaten cilantro."],"t":"～たことがあります (experience)","p":"ta-form ＋ことがあります"},"n4-11":{"cat":"Expressions & Sentence Patterns","ex":"Gives advice or a suggestion. 「た形＋ほうがいい」means \"had better do ~ / it's better to do ~,\" while 「ない形＋ほうがいい」means \"had better not do ~.\"","eg":["You'd better make a reservation early.","When your throat hurts, you'd better not force yourself to talk."],"t":"～ほうがいいです","p":"ta-form ＋ほうがいい／nai-form ＋ほうがいい"},"n4-12":{"cat":"Expressions & Sentence Patterns","ex":"Means \"too much / excessively ~,\" indicating that something exceeds an appropriate degree. Attach to the verb stem (ます-form minus ます), to an い-adjective minus 「い」, or to a な-adjective stem.","eg":["I played video games too much yesterday.","This seasoning is too strong."],"t":"～すぎます (excess)","p":"masu-form (drop ます) ＋すぎます／i-adjective (drop い) ＋すぎ／na-adjective ＋すぎ"},"n4-13":{"cat":"Obligation & Permission","ex":"Means \"may / it's okay to do ~,\" granting permission. Attach 「もいいです」 to the て-form. As a question, it asks for permission (\"May I ~?\").","eg":["May I use this chair?","You may take the day off tomorrow."],"t":"～てもいいです (permission)","p":"te-form ＋もいいです"},"n4-14":{"cat":"Obligation & Permission","ex":"Means \"must not / may not do ~,\" expressing prohibition. Attach 「はいけません」 to the て-form.","eg":["You must not eat or drink inside the building.","You must not touch your smartphone while driving."],"t":"～てはいけません (prohibition)","p":"te-form ＋はいけません"},"n4-15":{"cat":"Obligation & Permission","ex":"Means \"don't have to / it's okay not to do ~,\" expressing that an action is unnecessary. Take the ない-form, drop 「ない」, and add 「なくてもいいです」.","eg":["You don't have to work overtime today.","There's no need to panic."],"t":"～なくてもいいです (not necessary)","p":"nai-form (drop ない) ＋なくてもいいです"},"n4-16":{"cat":"Obligation & Permission","ex":"Means \"must / have to do ~,\" expressing obligation or necessity. Take the ない-form, drop 「ない」, and add 「なければなりません」. The casual spoken contraction is 「なきゃ」.","eg":["I have to submit the report by next week.","I have to attend the first meeting in the morning."],"t":"～なければなりません (obligation)","p":"nai-form (drop ない) ＋なければなりません"},"n4-17":{"cat":"Conjunctions & Cause","ex":"Means \"in order to do ~ / for the sake of ~,\" expressing a deliberate, volitional purpose. Attach to the dictionary form of a verb, or to 「名詞＋の」.","eg":["I go to the library every day in order to pass the certification exam.","I work hard for the sake of my family."],"t":"～ために (purpose)","p":"dictionary form／noun の＋ために"},"n4-18":{"cat":"Conjunctions & Cause","ex":"Means \"because of ~,\" a relatively objective way of stating a cause (often for negative or notable results). Attach to the た-form of a verb, or to 「名詞＋の」.","eg":["Because of the heavy snow, the Shinkansen was suspended.","Because a system failure occurred, the work was delayed."],"t":"～ために (cause)","p":"ta-form／noun の＋ために"},"n4-19":{"cat":"Conjunctions & Cause","ex":"Means \"so that ~ / in order to be able to ~.\" Used with non-volitional verbs, potential forms, or negative forms (something you hope will happen rather than a direct action you control).","eg":["I set two alarms so that I won't oversleep.","I review every night so that I can pass the exam."],"t":"～ように (purpose)","p":"dictionary form／nai-form ＋ように"},"n4-20":{"cat":"Conjunctions & Cause","ex":"Attach to the dictionary form. 「ようになる」expresses a natural change that has come about as a result (\"come to be able to ~ / reach the point where ~\"). 「ようにする」expresses making a conscious, ongoing effort to do something.","eg":["I've become able to eat spicy food.","I'm making an effort to go to bed early and get up early."],"t":"～ようになります・～ようにします","p":"dictionary form ＋ようになる (change)／ようにする (effort)"},"n4-21":{"cat":"Conjunctions & Cause","ex":"Lists multiple reasons or qualities: \"both A and B (and so...).\" Often implies there are further reasons beyond those stated. Attaches to the plain form.","eg":["The view is great and the service is attentive, so I love this inn.","It's raining and I'm tired, so let's go home by taxi."],"t":"Particle「し」(listing reasons)","p":"plain form ＋し"},"n4-22":{"cat":"Conjunctions & Cause","ex":"Means \"even if ~ / even though ~,\" expressing that the result holds despite the condition. Attach 「も」 to the て-form. Often paired with 「何度～ても」(\"no matter how many times ~\").","eg":["Even if I don't feel well, I'll play in the match.","No matter how many times I read it, I can't understand the meaning."],"t":"～ても (concessive condition)","p":"te-form ＋も"},"n4-23":{"cat":"Aspect","ex":"\"To try doing something (and see how it goes).\" The 「て」-form + 「みます」 expresses giving an action a try to find out the result or experience it.","eg":["I'll try going to that new café.","Please give this method a try."],"t":"～てみます (try)","p":"te-form ＋みます"},"n4-24":{"cat":"Aspect","ex":"The 「て」-form + 「しまいます」 expresses ① completing an action entirely, or ② doing something by accident / with a sense of regret. Colloquially it contracts to 「ちゃう」.","eg":["I ended up watching the whole TV series in one night.","I accidentally left my notebook on the train."],"t":"～てしまいます (completion・regret)","p":"te-form ＋しまいます"},"n4-25":{"cat":"Aspect","ex":"The 「て」-form + 「おきます」 means to do something in advance in preparation, or to leave something as it is.","eg":["I'll buy the ticket in advance before my business trip.","Please leave the dishes in the sink."],"t":"～ておきます (advance preparation)","p":"te-form ＋おきます"},"n4-26":{"cat":"Aspect","ex":"The 「て」-form + 「きます」 indicates movement toward the speaker or a change developing up to the present; the 「て」-form + 「いきます」 indicates movement away from the speaker or a change continuing on into the future.","eg":["The atmosphere of the town has gradually changed (up to now).","From now on prices will keep going up."],"t":"～てきます・～ていきます","p":"te-form ＋きます (toward speaker)／te-form ＋いきます (away from speaker)"},"n4-27":{"cat":"Aspect","ex":"Attached to the 「ます」-stem (drop 「ます」), 「はじめる」 marks the start of an action, 「続ける」 marks its continuation, and 「終わる」 marks its completion.","eg":["The wind started to blow.","I kept running for 5 kilometers."],"t":"～はじめます・～続けます・～終わります","p":"masu-form (drop ます) ＋はじめる／続ける／終わる"},"n4-28":{"cat":"Aspect","ex":"「ところです」 pinpoints the stage of an action: dictionary form + 「ところ」 = about to do it; 「ている」+「ところ」 = in the middle of doing it; 「た」+「ところ」 = just finished doing it.","eg":["I'm just about to go to the meeting.","I'm in the middle of taking a bath right now.","I've just arrived at the station."],"t":"～ところです (action stage)","p":"dictionary form ところ (about to)／ているところ (in progress)／たところ (just finished)"},"n4-29":{"cat":"Aspect","ex":"\"Have just done ~.\" The 「た」-form + 「ばかりです」 emphasizes that only a short time has passed since the action was completed (this can be a subjective feeling, unlike 「たところ」 which is strictly objective).","eg":["I've just joined this company.","I just brushed my teeth a moment ago."],"t":"～たばかりです","p":"た form ＋ ばかりです"},"n4-30":{"cat":"Giving and Receiving","ex":"These express the giving and receiving of an action (a favor). 「てあげる」 = do something for someone else; 「てもらう」 = have someone do something for you; 「てくれる」 = someone does something for you (the speaker/in-group).","eg":["I gave my junior colleague some advice.","I had a colleague correct the document for me.","My older sister knitted a scarf for me."],"t":"～てあげます・てもらいます・てくれます","p":"て form ＋ あげる (do for someone)／もらう (have someone do)／くれる (someone does for me)"},"n4-31":{"cat":"Conjecture / Appearance","ex":"\"It looks like ~ / seems about to ~.\" A guess based on visual appearance. Attach 「そう」 to the 「ます」-stem of verbs (drop 「ます」), to い-adjectives (drop 「い」), or directly to な-adjectives.","eg":["It looks like a typhoon is coming.","That soup looks hot."],"n":"Exceptions: いい → よさそう, ない → なさそう.","t":"～そうです (appearance/inference)","p":"masu-form (drop ます) ＋ そうです／i-adjective (drop い) ＋ そう／na-adjective ＋ そう"},"n4-32":{"cat":"Conjecture / Appearance","ex":"\"I hear that ~ / They say that ~.\" Plain form + 「そうです」 reports information heard from another source (hearsay), passing it on without change.","eg":["I hear the new president is strict.","I hear next week's concert has been canceled."],"t":"～そうです (hearsay)","p":"plain form ＋ そうです"},"n4-33":{"cat":"Conjecture / Appearance","ex":"\"It seems / appears that ~.\" A conjecture based on the speaker's own observation or evidence. 「ようです」 is more formal; 「みたいです」 is the more colloquial equivalent.","eg":["It seems the neighbors have moved out.","It seems there was an earthquake last night."],"t":"～ようです・～みたいです","p":"plain form ＋ ようです (more formal)／みたいです (colloquial)"},"n4-34":{"cat":"Conjecture / Appearance","ex":"Plain form + 「らしいです」 has two uses: ① \"I hear that ~\" (a conjecture based on hearsay or outside information), and ② \"is very ~ like / typical of\" (having the characteristic qualities of something).","eg":["I hear Nakamura-san is going to change jobs.","She really is a person who is every bit the artist."],"t":"～らしいです","p":"plain form ＋ らしいです"},"n4-35":{"cat":"Conjecture / Appearance","ex":"\"It should be ~ / I'm sure that ~.\" Plain form + 「はずです」 states a logical inference the speaker is confident about, based on solid grounds. The negative 「はずがない」 means \"there's no way that ~ / it can't be that ~.\"","eg":["By the reserved time the seats should already be secured.","There's no way someone who prepared that much would fail."],"t":"～はずです","p":"plain form ＋ はずです"},"n4-36":{"cat":"Conjecture / Appearance","ex":"Plain form + 「でしょう／だろう」 expresses a conjecture (\"probably ~\") or seeks confirmation (\"~, right?\"). 「でしょう」 is polite; 「だろう」 is the plain form.","eg":["The temperature will probably drop over the weekend.","That restaurant is probably popular."],"t":"～でしょう・～だろう","p":"plain form ＋ でしょう (polite)／だろう (plain)"},"n4-37":{"cat":"Comparison","ex":"\"Compared to B, A is more ~.\" Used with the pattern 「BよりAのほうが」 + adjective to say that A ranks higher than B in some quality.","eg":["The express train is more comfortable than the local train.","The countryside is more relaxing than the city."],"t":"～より…ほうが","p":"B より A のほうが ＋ adjective"},"n4-38":{"cat":"Comparison","ex":"\"A is not as ~ as B.\" The pattern 「AはBほど」 + negative adjective states that A falls short of B in some quality.","eg":["Kyoto doesn't have as many people as Tokyo.","This winter isn't as cold as last year."],"t":"～ほど…ない","p":"A は B ほど ＋ adjective negative"},"n4-39":{"cat":"Comparison","ex":"\"The most ~ in/among ~.\" The superlative pattern: scope + 「で」 + 「いちばん」 + adjective, marking the top item within a given group or range.","eg":["What is the longest river in Asia?","The one who cooks best in my family is my mother."],"t":"～でいちばん (superlative)","p":"scope ＋ で ＋ いちばん ＋ adjective"},"n4-40":{"cat":"Quotation / Thought","ex":"Plain form + 「と言います」 quotes what someone said. It can be a direct quotation (in 「」) or an indirect quotation.","eg":["The department manager said, \"A new system starts next month.\"","My colleague said (that) he had caught a cold."],"t":"～と言います","p":"plain form ＋ と言います"},"n4-41":{"cat":"Quotation / Thought","ex":"\"I think that ~.\" Plain form + 「と思います」 states the speaker's own opinion or conjecture.","eg":["I think his proposal is reasonable.","I think this design has good taste."],"t":"～と思います","p":"plain form ＋ と思います"},"n4-42":{"cat":"Quotation / Thought","ex":"\"I intend to ~ / I'm thinking of ~ing.\" The volitional form + 「と思います」 expresses the speaker's intention or plan. The 「と思っています」 form implies the intention has been held for a while.","eg":["This year for sure I intend to take on the certification exam.","I'm thinking of applying to work from home."],"t":"～うと思います (intention)","p":"volitional form ＋ と思います"},"n4-43":{"cat":"Quotation / Thought","ex":"Plain form + 「か（どうか）」 forms an embedded (indirect) question meaning \"whether ~\" / \"whether or not ~.\" Use 「か」 with a question word already present, and 「かどうか」 for yes/no questions.","eg":["It hasn't been decided yet whether I can attend the party.","Please check whether I have any free time on the weekend."],"t":"～か（どうか）(indirect question)","p":"plain form ＋ か（どうか）"},"n4-44":{"cat":"Quotation / Thought","ex":"Describes a third person's desire or feeling from an outside perspective. Attach 「がる／がっている」 to the stem of a 「たい」 form or a desire adjective (drop the final 「い」), since you cannot state another person's feelings as direct fact.","eg":["My younger brother wants a new game console.","My niece wants to work abroad."],"t":"～がります (third-person desire)","p":"i-adjective (drop い) ＋ がります"},"n4-45":{"cat":"Expression / Sentence Pattern","ex":"Adds emphasis or explanation, or asks for/gives a reason or background. Very common in speech. Signals that the speaker is explaining a situation, seeking an explanation, or reacting to something observed.","eg":["Are you not feeling well? (You look pale — what's going on?)","Actually, I'm going to change jobs."],"t":"～んです・～のです","p":"plain form ＋ んです (na-adjective/noun: な＋んです)"},"n4-46":{"cat":"Expression / Sentence Pattern","ex":"A gentle command. Used by someone in a higher position toward someone lower — typically parents to children or teachers to students. Formed from the ます-stem plus なさい.","eg":["Do your homework first.","Wash your hands properly."],"t":"～なさい (command/instruction)","p":"masu-form (drop ます) ＋ なさい"},"n4-47":{"cat":"Expression / Sentence Pattern","ex":"「ことになる」= something is decided by external circumstances or by others (an outcome). 「ことにする」= the speaker makes the decision themselves. Attach to the dictionary form of the verb.","eg":["It has been decided that I will transfer to the Okinawa branch starting next month. (decided by the company)","I've decided to stop snacking. (my own decision)"],"t":"～ことになります・～ことにします","p":"dictionary form ＋ ことになる (decided by others)／ことにする (decided by oneself)"},"n4-48":{"cat":"Expression / Sentence Pattern","ex":"Means \"while remaining in the state of ~\" — an action is done, or a situation continues, without changing that existing state. Attach to the た-form, the ない-form, or 名詞＋の.","eg":["I ended up taking a shower with my glasses still on.","I left the house with the door still open."],"t":"～まま (state maintained)","p":"た form ＋ まま／nai-form ＋ まま／noun の ＋ まま"},"n4-49":{"cat":"Expression / Sentence Pattern","ex":"Means \"be always doing (nothing but) ~.\" Formed with the て-form + ばかりいる. Carries a critical, disapproving tone that the person does one thing to excess.","eg":["Don't just read comics all the time — go study.","I'm always eating out."],"t":"～ばかり (doing nothing but)","p":"verb て form ＋ ばかりいる"},"n4-50":{"cat":"Expression / Sentence Pattern","ex":"Means \"in the case (event) of ~\" / \"when ~ happens.\" More formal than たら and often used in rules, instructions, and manuals. Attach to the plain form (な-adjective and noun take の＋場合).","eg":["In the event of an earthquake, please take cover under a desk.","If a problem occurs, please contact the administrator."],"t":"～場合 (conditional/hypothetical)","p":"plain form ＋ 場合 (na-adjective/noun: の＋場合)"},"n4-51":{"cat":"Verb Conjugation","ex":"The volitional form, meaning \"let's ~\" or \"I think I'll ~.\" It is the plain-style form of suggestion/invitation. Godan (五段): change the final -u sound to the matching -ou sound (行く→行こう). Ichidan (一段): drop る and add よう. Irregulars: する→しよう, 来る→来よう.","eg":["Let's try out the new shop.","Let's all make a toast together."],"t":"Volitional form","p":"godan: u-row→o-row／ichidan: drop る＋よう"},"n4-52":{"cat":"Verb Conjugation","ex":"The potential form, meaning \"can / be able to do ~.\" The object of the ability is usually marked with が. Godan: change the final -u sound to the -e sound and add る (書く→書ける). Ichidan: drop る and add られる. In casual speech, the ら of ichidan verbs is often dropped (食べられる→食べれる).","eg":["I can write Korean.","I can eat raw egg."],"t":"Potential form","p":"godan: u-row→e-row＋る／ichidan: drop る＋られる"},"n4-53":{"cat":"Verb Conjugation","ex":"Imperative form = a direct order (\"Do ~!\"). Prohibitive form = \"Don't ~! / You must not ~!\" Both are very forceful and blunt. Imperative: godan verbs shift to the -e sound (走る→走れ); prohibitive is the dictionary form + な (入る→入るな).","eg":["Run faster!","Don't come into this room!"],"t":"Imperative form・Prohibitive form","p":"imperative: godan e-row／prohibitive: dictionary form＋な"},"n4-54":{"cat":"Verb Conjugation","ex":"The conditional ば-form, meaning \"if ~ (then).\" Expresses a hypothetical condition. Godan: change the final -u sound to the -e sound and add ば (合う→合えば). Ichidan: drop る and add れば.","eg":["If our schedules match, let's go for tea or something.","If it's cheap, I'll buy it."],"t":"Conditional form (ba-form)","p":"godan: u-row→e-row＋ば／ichidan: drop る＋れば"},"n4-55":{"cat":"Conditional Expressions","ex":"Means \"if / when ~ (has happened).\" The most versatile and general conditional. Formed with the た-form + ら. It can also express an unexpected discovery — doing A and then finding out B.","eg":["When the train comes, please get on right away.","When I opened the door, I found a letter had fallen on the floor."],"t":"～たら (conditional)","p":"た form ＋ ら"},"n4-56":{"cat":"Conditional Expressions","ex":"Means \"if it's the case that ~ / if you're talking about ~.\" It picks up a topic just raised (often by the other person) and gives advice or a suggestion based on it. Attach to the plain form.","eg":["If you're going to a hot spring, I recommend Hakone.","If the rent is within my budget, I'd like to sign the contract."],"t":"Particle「なら」(conditional)","p":"plain form ＋ なら"},"n4-57":{"cat":"Conditional Expressions","ex":"Means \"whenever A, B\" / \"as soon as A, B\" — expressing an inevitable, automatic result. Used for natural laws, habitual/repeated results, and how machines or devices work. Attach と to the dictionary form. The result clause cannot express the speaker's will, request, or invitation.","eg":["When night falls, the town's lights come on.","When you turn this key, the safe opens."],"t":"Conjunctive particle「と」(constant condition)","p":"dictionary form ＋ と"},"n4-58":{"cat":"Conditional Expressions","ex":"Combines a conditional (たら / ば / と) with いいです to give advice (\"you should ~ / it'd be good to ~\") or to express a wish/hope (\"I hope ~\").","eg":["You should talk it over with a doctor.","I hope the new store opens."],"t":"～たら／ば／といいです (suggestion/hope)","p":"たら／ば／と ＋ いいです"},"n4-59":{"cat":"Verb Conjugation","ex":"The passive form, meaning \"be ~ed / have ~ done to one.\" Covers the direct passive as well as the indirect (\"adversative\") passive, where the subject is affected — often negatively — by an action. Godan: shift to the -a sound and add れる (認める→認められる via the ichidan rule; 書く→書かれる). Ichidan: drop る and add られる.","eg":["My proposal was approved by the section chief.","I had my wallet pickpocketed at the station."],"t":"Passive form","p":"godan: a-row＋れる／ichidan: drop る＋られる"},"n4-60":{"cat":"Verb Conjugation","ex":"The causative form, meaning \"make / let someone do ~.\" Expresses either forcing someone to do something or permitting them to. Godan: shift to the -a sound and add せる (書く→書かせる). Ichidan: drop る and add させる. The person made/let to act is marked with に (or を with intransitive verbs).","eg":["The teacher makes the students write compositions.","The store manager let the part-timer go home early."],"t":"Causative form","p":"godan: a-row＋せる／ichidan: drop る＋させる"},"n4-61":{"cat":"Verb Conjugation","ex":"The causative-passive form, meaning \"be made to do ~ (against one's will).\" Expresses being forced or compelled to do something reluctantly. Godan: shift to the -a sound and add される (発表する uses する→させられる; 書く→書かされる). Ichidan: drop る and add させられる.","eg":["I'm made to give a presentation at the meeting every week.","As a child, I was forced to eat the green peppers I disliked."],"t":"Causative-passive form","p":"godan: a-row＋される／ichidan: drop る＋させられる"},"n4-62":{"cat":"Honorific Language (Keigo)","ex":"Respectful language (尊敬語) that elevates the actions of the person you're speaking to or about. General pattern: お＋ます-stem＋になります. Some verbs have special respectful forms: いらっしゃいます (be/go/come), おっしゃいます (say), ご覧になります (look/see), etc.","eg":["What time will the department manager be back?","What did the teacher say?"],"t":"Honorific language","p":"お＋masu-form＋になります／special honorific words"},"n4-63":{"cat":"Honorific Language (Keigo)","ex":"Humble language (謙譲語) that lowers your own actions to show respect to the other party. General pattern: お＋ます-stem＋します. Some verbs have special humble forms: 参ります (go/come), 申します (say/be called), 拝見します (look/see), etc.","eg":["I'll take care of your luggage.","I will attend next week's meeting."],"t":"Humble language","p":"お＋masu-form＋します／special humble words"},"n4-64":{"cat":"Honorific Language (Keigo)","ex":"Means \"please allow me to ~ / I will humbly ~.\" A very polite way to ask permission or announce that you'll do something, framing your action as being permitted by the listener. Formed from the causative て-form + いただきます.","eg":["I'll be taking paid leave tomorrow (with your permission).","Allow me to hand out the materials."],"t":"～させていただきます","p":"causative form て ＋ いただきます"},"n4-65":{"cat":"Honorific Language (Keigo)","ex":"An overview of polite/beautifying prefixes and words. お attaches to native Japanese (和語) words and ご to Sino-Japanese (漢語) words to make them polite (お名前, ご住所). ございます is the polite equivalent of あります (\"there is / to have\").","eg":["What time is your reservation?","Is there something I can help you with? / Is anything the matter?"],"t":"Keigo overview (お/ご・ございます)","p":"お＋native Japanese word／ご＋Sino-Japanese word (beautifying language)"},"n4-66":{"cat":"Colloquial / Particles","ex":"Contracted forms used in everyday casual speech: ている→てる, ておく→とく, てしまう→ちゃう (and でしまう→じゃう).","eg":["What are you looking at? (＝見ている)","I went and lost my ticket. (＝落としてしまった)"],"t":"Contracted expressions (colloquial)","p":"ている→てる、ておく→とく、てしまう→ちゃう"},"n4-67":{"cat":"Colloquial / Particles","ex":"Means \"no matter ~ / any ~ at all.\" A question word + \"でも\" expresses total, unrestricted affirmation, covering every possible case (anywhere, anytime, anyone, anything, etc.).","eg":["I can study anywhere.","Please contact me anytime."],"t":"Particle「でも」(universal affirmation)","p":"question word ＋ でも"},"n4-68":{"cat":"Colloquial / Particles","ex":"A casual, colloquial way to list examples (\"~ and ~ and things like that\"). More informal and offhand than \"や,\" and it implies the list is only a partial selection of examples.","eg":["I bought some tea and snacks and things like that.","Do you want to go do karaoke or something?"],"t":"Particle「とか」(listing)","p":"noun ＋ とか ＋ noun ＋ とか"},"n4-69":{"cat":"Expressions / Sentence Patterns","ex":"Equivalent to \"ないで\" (\"without doing ~\"), but more written/formal. Attach \"ず(に)\" to the ない-form stem. Note the irregular form: \"する\" becomes \"せず.\"","eg":["I moved without telling anyone.","I went out without locking the door."],"t":"～ず・～ずに","p":"nai-form (drop ない) ＋ ず（に）"},"n4-70":{"cat":"Expressions / Sentence Patterns","ex":"The formal noun \"こと\" nominalizes a verb phrase, turning a whole clause into a noun. Similar to \"の,\" but more written/abstract and preferred for stating general facts, rules, or ideas.","eg":["My joy in life is growing flowers.","Keeping to your schedule is the basis of trust."],"t":"Formal noun「こと」","p":"plain form ＋ こと"},"n4-71":{"cat":"Expressions / Sentence Patterns","ex":"\"Noun + がする\" expresses a sensory perception. Used with things you sense involuntarily, such as sounds (音), tastes (味), smells (匂い・香り), and feelings (気).","eg":["There's a sweet fragrance.","There's a burnt smell."],"t":"～がします (sensory perception)","p":"noun ＋ がします"},"n4-72":{"cat":"Expressions / Sentence Patterns","ex":"The suffix \"~さ\" turns an adjective into a noun expressing its degree or extent. Attach it to the stem of an i-adjective (drop 「い」) or to a na-adjective.","eg":["This lake's depth is 50 meters.","The cold of winter cuts to the bone."],"t":"Suffix「～さ」","p":"i-adjective (drop い) ＋ さ／na-adjective ＋ さ"},"n4-73":{"cat":"Expressions / Sentence Patterns","ex":"\"Dictionary form + ことがあります\" means \"sometimes ~ / it can happen that ~.\" It expresses an occasional possibility rather than a habit. (Distinct from \"た-form + ことがある,\" which means \"have ever done ~.\")","eg":["During the busy season, shipping is sometimes delayed.","This elevator sometimes breaks down."],"t":"～ことがあります (possibility)","p":"dictionary form ＋ ことがあります"},"n4-74":{"cat":"Verb Conjugation","ex":"The passive form (れる・られる) can also be used to show respect toward the subject (honorific/尊敬語). The form is identical to the passive: for godan verbs use the あ-row + れる; for ichidan verbs drop る + られる. Context tells you whether it's passive or honorific.","eg":["The company president has already departed. (honorific)","What will the section chief order? (honorific)"],"t":"Honorific form (れる・られる)","p":"godan: a-row＋れる／ichidan: drop る＋られる"},"n4-75":{"cat":"Verb Conjugation","ex":"All verb conjugations start from the dictionary form and branch out (ます-form → て-form → potential → passive → causative, etc.). The key is first identifying the verb's class (godan / ichidan / irregular), since each class conjugates differently.","eg":["\"飲む\" (to drink): 飲みます / 飲んで / 飲める / 飲まれる / 飲ませる — an overview of the conjugations.","\"見る\" (to see): 見ます / 見て / 見られる / 見させる — an overview of the conjugations."],"t":"Verb conjugation order","p":"masu-form→て form→potential form→passive form→causative form, etc."}};
const N3_EN = {"n3-1":{"cat":"Connectives / Cause","ex":"Means \"in / at ~.\" Indicates a place, situation, or field/domain. A more formal, written equivalent of the particle \"で.\" Use \"において\" before a verb and \"における\" before a noun.","eg":["The general assembly was held in Kyoto.","The information gap in modern society is serious.","A traditional crafts exhibition was held in the Tohoku region."],"t":"～において・～における","p":"noun ＋ において／における ＋ noun"},"n3-2":{"cat":"Connectives / Cause","ex":"Means \"toward / with respect to ~.\" Indicates the target/object of an action or attitude, or sets up a contrast between two things. Use \"に対して\" before a verb/clause and \"に対する\" before a noun.","eg":["I make a point of using polite language toward customers.","The older brother is introverted, whereas the younger brother is sociable.","The board members' reaction to the new proposal was cool."],"t":"～に対して","p":"noun ＋ に対して／に対する ＋ noun"},"n3-3":{"cat":"Connectives / Cause","ex":"Means \"about / concerning ~.\" Indicates the topic or content being discussed. Use \"について\" before a verb and \"についての\" before a noun.","eg":["I'll explain about the new product in detail.","I attended a seminar about regional revitalization.","I have a question about the hiring interview."],"t":"～について","p":"noun ＋ について／についての ＋ noun"},"n3-4":{"cat":"Connectives / Cause","ex":"\"によって / による\" has several uses: (1) \"by means of / due to ~\" (method or cause); (2) \"depending on ~ / varies according to ~\"; (3) marks the agent (doer) in a passive sentence (\"by ~\").","eg":["Food culture varies from region to region.","The blackout caused by the typhoon is continuing.","This novel was written by a famous author."],"t":"～によって・～による","p":"noun ＋ によって／による ＋ noun"},"n3-5":{"cat":"Connectives / Cause","ex":"Means \"as ~ / in the role/capacity of ~.\" Indicates a status, standpoint, or qualification. Attaches directly to a noun.","eg":["I came to this university as an exchange student.","Nara is known worldwide as an ancient capital.","I headed to the disaster area as a volunteer."],"t":"～として","p":"noun ＋ として"},"n3-6":{"cat":"Connectives / Cause","ex":"Means \"thanks to ~.\" States a positive cause and carries a tone of gratitude. Use plain form + \"おかげで\" or \"noun + の + おかげで.\"","eg":["Thanks to my senior colleague, I was able to deliver the goods without a hitch.","Thanks to the good weather, we could enjoy the hike.","Thanks to the scholarship, studying abroad became a reality."],"t":"～おかげで","p":"plain form ＋ おかげで／noun の ＋ おかげで"},"n3-7":{"cat":"Connectives / Cause","ex":"Means \"because of ~ / it's ~'s fault.\" States a negative cause (blame). \"せいか\" softens this to \"perhaps because ~,\" expressing an uncertain reason. Use plain form + \"せいで\" or \"noun + の + せいで.\"","eg":["Because of the heavy snow, the expressway was closed.","Perhaps because I'm short on sleep, my head feels foggy.","Because of the system failure, no employee in the whole company could leave on time."],"t":"～せいで・～せいか","p":"plain form ＋ せいで／noun の ＋ せいで"},"n3-8":{"cat":"Connectives / Cause","ex":"Means \"for ~ / from ~'s point of view.\" Expresses a particular person's or group's standpoint or perspective. Attaches directly to a noun.","eg":["For me, reading on the weekend is the greatest luxury.","For students job-hunting, this information is valuable.","For elderly people, operating a smartphone can be difficult."],"t":"～にとって","p":"noun ＋ にとって"},"n3-9":{"cat":"Connectives / Cause","ex":"Means \"along with / as ~ / together with ~.\" Expresses a change happening in parallel with another (as one thing progresses, so does another) or doing something jointly with someone. Follows a noun or a dictionary-form verb.","eg":["My physical strength has declined with age.","I welcomed the new year in our new home together with my family.","Along with the advance of technology, ways of working have also diversified."],"t":"～とともに","p":"noun ＋ とともに／dictionary form ＋ とともに"},"n3-10":{"cat":"Time","ex":"\"ところだ\" pinpoints one of three stages of an action: dictionary form + ところだ = \"about to do ~\"; ている + ところだ = \"in the middle of doing ~\"; た-form + ところだ = \"have just done ~.\"","eg":["I'm just about to head out for lunch.","I've just this moment finished the proposal.","I'm in the middle of tallying the data."],"t":"～ところだ","p":"dictionary form ＋ ところだ (about to) ／ている ＋ ところだ (in the middle of) ／た ＋ ところだ (just did)"},"n3-11":{"cat":"Time","ex":"Means \"just did ~ / only just ~,\" stressing that an action was completed a very short time ago. Must attach to the た-form: sentence-final \"~たばかりだ,\" connective \"~たばかりで,\" or noun-modifying \"~たばかりの.\" Note: \"dictionary form + ばかりだ\" (e.g. 悪化するばかりだ) is a different grammar meaning \"keeps getting more and more ~\"—don't confuse the two.","eg":["I just got back to my home country, so I'm still jet-lagged.","I just woke up, so my head is still foggy.","I've just been assigned to this project, so I don't know my way around at all."],"t":"～たばかり","p":"verb ta-form ＋ ばかり (だ／で／の)"},"n3-12":{"cat":"Time","ex":"Means \"right in the middle of ~ing / at the height of ~.\" Emphasizes the peak or thick of an ongoing action or event. Use ている + 最中に or \"noun + の + 最中に.\"","eg":["Right in the middle of the presentation, the power went out.","Right in the middle of my meal, an urgent call came in.","In the middle of the interview, my phone rang."],"t":"～最中に","p":"ている ＋ 最中に／noun の ＋ 最中に"},"n3-13":{"cat":"Time","ex":"Means \"while ~ / during the time that ~ (before it changes).\" You do something taking advantage of a current state, implying that the opportunity or condition won't last. Connects to dictionary/ない-form, i-adjective, な-adjective + な, or \"noun + の.\"","eg":["I want to travel to many countries while I'm still young.","Let's write up the minutes while the memory is still fresh.","Let's come down from the mountain while it's still light out."],"t":"～うちに","p":"dictionary form／nai-form／i-adjective い／na-adjective な／noun の ＋ うちに"},"n3-14":{"cat":"Time","ex":"\"During ~ / while ~.\" Indicates that something happens at some point within a certain period of time. The action in the main clause typically occurs once, at an unspecified moment, before that period ends. Attaches to dictionary form, the ~ている form, or 「名詞＋の」.","eg":["A parcel was delivered while I was out.","The phone was ringing while I was taking a shower.","While I was away on a business trip, a personnel reshuffle was announced at the company."],"t":"～間に","p":"dictionary form ＋ 間に／ている ＋ 間に／noun の ＋ 間に"},"n3-15":{"cat":"Time","ex":"\"While one is at it / on the same occasion.\" Indicates doing a second thing incidentally while doing a main action. Attaches to dictionary form, ~た form, or 「名詞＋の」.","eg":["While I was out shopping, I went to pick up the dry cleaning.","While taking a walk, I dropped a letter in the mailbox.","Since I had stopped by the bookstore anyway, I also bought some stationery."],"t":"～ついでに","p":"dictionary form／ta-form ＋ ついでに／noun の ＋ ついでに"},"n3-16":{"cat":"Time","ex":"\"Unless one does ~ first, (something else cannot happen).\" Expresses that completing the first action is a necessary precondition for the second. The main clause is usually negative or expresses impossibility. Attaches to the て form + 「からでないと／からでなければ」.","eg":["You cannot enter the store unless you make a reservation first.","I can't sign unless I check the contract terms first.","We cannot permit entry to the building unless you show your ID first."],"t":"～てからでないと","p":"te-form ＋ からでないと／からでなければ"},"n3-17":{"cat":"Condition / Hypothesis","ex":"\"As long as / if only ~, then ~.\" Expresses the minimum sufficient condition for a result. With nouns use 「名詞＋さえ＋動詞ば形」; with verbs use 「動詞ます形＋さえすれば」.","eg":["As long as you have your health, you'll manage somehow.","As long as you just follow the procedure, you won't fail.","As long as I have you, I don't need anything else."],"t":"～さえ～ば","p":"noun ＋ さえ ＋ verb ba-form／verb masu-form ＋ さえすれば"},"n3-18":{"cat":"Condition / Hypothesis","ex":"\"Supposing / assuming that ~.\" Sets up a hypothetical situation and considers its consequences. Attaches to the plain form + 「としたら／とすれば／とすると」.","eg":["If I were to win the lottery, I'd want to build a house.","If it rains tomorrow, the sports day will probably be postponed.","Supposing we were to double the budget, we would need to review the entire plan."],"t":"～としたら・～とすれば","p":"plain form ＋ としたら／とすれば／とすると"},"n3-19":{"cat":"Condition / Hypothesis","ex":"\"When/after I did ~, (I found that) ...\" Indicates that upon doing something, a particular result or discovery followed. The outcome is often unexpected or newly learned. Attaches to the ~た form + ところ.","eg":["When I inquired at the counter, I got an answer right away.","When I investigated in detail, the cause became clear.","When I tried out the new rice cooker, it was easier than I had expected."],"t":"～たところ","p":"ta-form ＋ ところ"},"n3-20":{"cat":"Condition / Hypothesis","ex":"\"The more ~, the more ~.\" Expresses that as one thing increases in degree, another correspondingly increases. Formed by repeating the verb: ば形 + dictionary form + ほど (e.g. 「すればするほど」).","eg":["The more you practice, the better you get.","The more I look into it, the more questions arise.","The more I thought about it, the less able I was to decide."],"t":"～ば～ほど","p":"ba-form ＋ dictionary form ＋ ほど"},"n3-21":{"cat":"Condition / Hypothesis","ex":"\"It's not that ~ can't be done.\" A double negative used to express a reluctant or hedged affirmative — it is possible, but with some reservation. Attaches to the ない form + 「ことはない／こともない」.","eg":["It's not that I can't attend, but my schedule is a bit tight.","It's not that I can't understand it, but I'm not convinced.","It's not that I can't eat spicy food, but I don't really like it."],"t":"～ないことはない・～ないこともない","p":"nai-form ＋ ことはない／こともない"},"n3-22":{"cat":"Scope / Limitation","ex":"\"Now that ~ / since ~, (one must ...).\" Expresses that once something is the case, a certain obligation or expected behavior naturally follows. The main clause typically states a duty, resolve, or something one should do. Attaches to the plain form + 「以上（は）」.","eg":["Now that I've made a promise, I should keep it properly.","Now that I've accepted the request, I'll take responsibility to the very end.","Now that I've been chosen as the representative, I intend to give it my all."],"t":"～以上（は）","p":"plain form ＋ 以上（は）"},"n3-23":{"cat":"Scope / Limitation","ex":"Two uses: (1) \"after doing ~ (and on that basis)\" — doing something first and then acting based on the result; (2) \"in terms of / with regard to ~.\" Attaches to dictionary form / ~た form + 上で, or 「名詞＋の＋上で」.","eg":["After discussing it thoroughly with my family, I decided to change jobs.","Relationships in the context of work are important.","When living alone, cooking skills are indispensable."],"t":"～上で","p":"dictionary form／ta-form ＋ 上で／noun の ＋ 上で"},"n3-24":{"cat":"Scope / Limitation","ex":"\"Instead of ~ / in place of ~.\" Indicates substituting one thing for another. It can also express an exchange or trade-off, where one action is compensated by another. Attaches to the plain form + 代わりに, or 「名詞＋の＋代わりに」.","eg":["I used honey instead of sugar.","In return for preparing the documents, I was treated to lunch.","The train was delayed, so instead of a taxi I headed there by rental bike."],"t":"～代わりに","p":"plain form ＋ 代わりに／noun の ＋ 代わりに"},"n3-25":{"cat":"Scope / Limitation","ex":"Two uses: 「に限り」 means \"limited to / only for ~\" (restricting the scope); 「に限って」 often means \"of all times, it had to be ~,\" expressing that something unwelcome happens at precisely the worst moment. Attaches to 「名詞＋に限り／に限って」.","eg":["Only the first 100 customers will receive a special gift.","It's precisely on the days I don't bring an umbrella that it suddenly rains.","It's exactly when I'm in a hurry that I get caught at the traffic lights."],"t":"～に限り・～に限って","p":"noun ＋ に限り／に限って"},"n3-26":{"cat":"Scope / Limitation","ex":"\"Just / only ~,\" or \"ever since ~, (nothing further has happened).\" Expresses either a limitation to a single scope, or that after one occurrence a state has continued unchanged. Attaches to the ~た form + きり, or 「名詞＋きり」.","eg":["I want to talk with you at length, just the two of us.","I met them at the class reunion, but since then we've been out of touch.","I went to that shop just once and haven't had the chance to go again."],"t":"～きり・～きりだ","p":"ta-form ＋ きり／noun ＋ きり"},"n3-27":{"cat":"Scope / Limitation","ex":"\"Starting with / such as ~ (among others).\" Cites one representative example to imply that others of the same kind also apply. Attaches to 「名詞＋をはじめ（として）」.","eg":["Starting with Kyoto, I also want to visit Nara and Kanazawa.","Starting with the executives, all the employees cooperated in the charity event.","Ramen, as well as sushi and tempura, are popular with foreigners."],"t":"～をはじめ（として）","p":"noun ＋ をはじめ（として）"},"n3-28":{"cat":"Scope / Limitation","ex":"\"Regarding / concerning ~.\" Indicates the topic or subject matter being addressed. It is more formal than 「について」. Use 「に関して」 before a verb and 「に関する」 before a noun. Attaches to 「名詞＋に関して／に関する＋名詞」.","eg":["Regarding this matter, I will report the details at a later date.","The guidelines concerning the working environment have been revised.","We received many opinions from users regarding the new service."],"t":"～に関して・～に関する","p":"noun ＋ に関して／に関する ＋ noun"},"n3-29":{"cat":"Comparison / Degree","ex":"\"For ~ / considering ~, (surprisingly) ...\" Indicates that the actual situation differs from what one would expect given the stated standard. Attaches to the plain form + わりに, or 「名詞＋の＋わりに」.","eg":["For how reasonable its prices are, this restaurant's food is surprisingly high quality.","For her age, her skin is remarkably youthful.","For what the advertisement suggested, the actual item was small."],"t":"～わりに","p":"plain form ＋ わりに／noun の ＋ わりに"},"n3-30":{"cat":"Comparison / Degree","ex":"\"For ~ / considering that it's ~, (contrary to expectation) ...\" Judges something against a standard that it fails to meet or exceeds unexpectedly. The contrast is stronger than with 「わりに」. Attaches to the plain form + にしては, or 「名詞＋にしては」.","eg":["For a professional, the finish is sloppy.","For a beginner, it's a well-balanced piece of work.","For someone in their first year living in Japan, you use honorific language really well."],"t":"～にしては","p":"plain form ＋ にしては／noun ＋ にしては"},"n3-31":{"cat":"Comparison / Degree","ex":"\"To the extent/degree that ~.\" Uses a concrete example to illustrate just how great a degree something reaches. Attaches to dictionary form + ほど, or 「名詞＋ほど」.","eg":["I was moved to the point of tears.","I walked around so much that my legs were wobbly.","I was so looking forward to it that I couldn't sleep."],"t":"～ほど","p":"dictionary form ＋ ほど／noun ＋ ほど"},"n3-32":{"cat":"Comparison / Degree","ex":"\"To the extent that ~.\" Like 「ほど」, it illustrates a degree by giving an example, and is often used for extreme degrees. Slightly more colloquial than 「ほど」. Attaches to dictionary form / 「名詞」 + くらい／ぐらい.","eg":["I was so nervous that my hands were shaking.","I was so surprised I couldn't get a word out.","During the morning commute, the trains are so crowded you can't even move."],"t":"～くらい・～ぐらい (degree)","p":"dictionary form／noun ＋ くらい"},"n3-33":{"cat":"Manner / Tendency","ex":"\"Seems like ~ / -ish,\" or \"prone to ~.\" A colloquial suffix expressing a quality, appearance, or a tendency to do something. Attaches to a noun, the stem of an い-adjective, or a verb ます-stem + っぽい.","eg":["Lately I've become forgetful.","This color is a little childish.","My younger brother has a fickle personality, so his hobbies never last."],"t":"～っぽい","p":"noun／i-adjective stem／verb masu-form ＋ っぽい"},"n3-34":{"cat":"Manner / Tendency","ex":"\"Tends to ~ / is apt to ~.\" Expresses a frequent or habitual tendency, most often used for negative or undesirable ones. Attaches to the verb ます-stem + がち, or 「名詞＋がち」.","eg":["In winter I tend to catch colds.","Living alone, one's diet tends to become unbalanced.","When I'm busy, I tend to skip meals."],"t":"～がち","p":"verb masu-form ＋ がち／noun ＋ がち"},"n3-35":{"cat":"Manner / Tendency","ex":"\"A bit ~ / slightly ~.\" Indicates a mild sign or slight tendency toward some state, usually a negative one. Attaches to the verb ます-stem + 気味, or 「名詞＋気味」.","eg":["Lately I've been putting on a bit of weight.","I feel like I'm coming down with a cold, so I'll go to bed early today.","I'm feeling a bit tired, so let's take it easy and rest this weekend."],"t":"～気味","p":"verb masu-form ＋ 気味／noun ＋ 気味"},"n3-36":{"cat":"Manner / Tendency","ex":"\"Leave something in a certain state and just leave it that way.\" It indicates that the result of an action continues unattended, and carries a negative nuance (something was left undone or neglected).","eg":["I fell asleep with the TV left on.","The documents have been left scattered all over the desk.","I went out and left the window wide open."],"t":"～っぱなし","p":"verb masu-form ＋ っぱなし"},"n3-37":{"cat":"Manner / Tendency","ex":"「向き」 = \"suited to / suitable for ~\" (naturally a good fit for a certain group). 「向け」 = \"designed for / aimed at ~\" (intentionally targeted at a certain group).","eg":["This seasoning is well suited to children.","A programming course for beginners.","This teaching material is designed for working adults."],"t":"～向き・～向け","p":"noun ＋ 向き／noun ＋ 向け"},"n3-38":{"cat":"Manner / Tendency","ex":"\"Keep on ~ing / just keeps getting more ~.\" It shows a continuous change in one direction, most often a negative one.","eg":["The rural population just keeps declining.","Prices just keep rising.","Environmental problems just keep getting worse."],"t":"～一方だ","p":"dictionary form ＋ 一方だ"},"n3-39":{"cat":"Manner / Tendency","ex":"\"Make an effort to ~ / take care to ~.\" It expresses making a conscious, deliberate effort to do (or, with the ない form, to avoid) something. Used with 「ている」 it means making it an ongoing habit.","eg":["I make a point of going to bed by 10 every night.","I make sure not to forget my promises.","I make a point of taking the stairs rather than the elevator."],"t":"～ようにする","p":"dictionary form／nai-form ＋ ようにする"},"n3-40":{"cat":"Manner / Tendency","ex":"\"Come to be able to ~ / come to ~.\" It expresses a natural change in ability or state over time (a shift from not doing/not being able to doing/being able).","eg":["I've become able to wake up at 6 in the morning.","My son has become able to read hiragana.","After going there many times, I've come to chat casually with the staff."],"t":"～ようになる","p":"dictionary form／nai-form ＋ ようになる"},"n3-41":{"cat":"Assertion / Emphasis","ex":"\"That is to say ~ / no wonder ~.\" It presents a conclusion that follows naturally and logically from the given circumstances.","eg":["He runs every morning, so no wonder he's good at marathons.","He worked abroad the whole time, so no wonder his English is fluent.","I drank three cups of coffee, so no wonder I can't sleep at night."],"t":"～わけだ","p":"plain form ＋ わけだ"},"n3-42":{"cat":"Assertion / Emphasis","ex":"\"There's no way ~ / it can't possibly be that ~.\" It strongly denies the possibility of something, based on the speaker's conviction.","eg":["There's no way you can succeed that easily.","There's no way he would fail to meet a deadline.","There's no way you can get the real thing at a price like this."],"t":"～わけがない","p":"plain form ＋ わけがない"},"n3-43":{"cat":"Assertion / Emphasis","ex":"\"It's not that ~ / it doesn't mean that ~.\" A partial denial used to clear up a misunderstanding, correcting an assumption the listener might have drawn.","eg":["It's not that I dislike it, I just wouldn't actively choose it.","It's not that I'm opposed to it.","It's not that I'm busy; I just feel down and can't get moving."],"t":"～わけではない","p":"plain form ＋ わけではない"},"n3-44":{"cat":"Assertion / Emphasis","ex":"\"Can't (bring myself to) ~\" (with the dictionary form) or \"can't not ~ / have no choice but to ~\" (with the ない form). It expresses being unable to do (or unable to avoid) something because of social obligation, morals, or one's position.","eg":["The deadline is tomorrow, so I can't just go home today.","Since they invited me, I can't very well turn it down.","I can't skip my boss's farewell party."],"t":"～わけにはいかない","p":"dictionary form／nai-form ＋ わけにはいかない"},"n3-45":{"cat":"Assertion / Emphasis","ex":"\"Should be ~ / ought to be ~.\" A confident inference based on some evidence or reasoning.","eg":["I made a reservation, so a seat should be secured.","I'm sure I sent the application, yet it seems it hasn't arrived.","This document should have the company president's seal on it."],"t":"～はずだ","p":"plain form ＋ はずだ"},"n3-46":{"cat":"Assertion / Emphasis","ex":"\"There's no way ~ / it can't be that ~.\" Based on evidence or reasoning, the speaker concludes that something couldn't possibly be the case.","eg":["There's no way she would make a mistake like that.","It's such a famous movie that there's no way anyone doesn't know it.","I locked the door, so there's no way anyone could get in."],"t":"～はずがない","p":"plain form ＋ はずがない"},"n3-47":{"cat":"Assertion / Emphasis","ex":"「ものだ」 = \"that's just the way it is / it's the nature of things\" (a general truth). 「ものではない」 = \"one shouldn't ~\" (a moral admonition about what's not proper to do).","eg":["People learn from their failures; that's just how it is.","You shouldn't speak ill of others in front of children.","As time passes, even painful things gradually fade from memory."],"t":"～ものだ・～ものではない","p":"dictionary form ＋ ものだ (general truth) ／ものではない (shouldn't do)"},"n3-48":{"cat":"Assertion / Emphasis","ex":"\"The thing to do is ~ / you should ~.\" Used to give someone advice or a strong recommendation about what to do (or, with the ない form, what not to do).","eg":["For your health, the thing to do is go to bed early and get up early.","If you want to reach your goal, the thing to do is make a plan.","If you don't want regrets, the thing to do is act the moment you think of it."],"t":"～ことだ","p":"dictionary form／nai-form ＋ ことだ"},"n3-49":{"cat":"Assertion / Emphasis","ex":"\"There's no need to ~ / you don't have to ~.\" It indicates that doing something is unnecessary, often used to reassure someone.","eg":["There's no need to blame yourself so much.","There's no need to rush, take your time.","There's no need to get down over something that trivial."],"t":"～ことはない","p":"dictionary form ＋ ことはない"},"n3-50":{"cat":"Assertion / Emphasis","ex":"「ことになる」 = a decision or outcome reached by external circumstances (something \"comes to be\" decided, often by others). 「ことにする」 = a decision made by oneself (\"I've decided to ~\").","eg":["It's been decided that I'll be transferred to the Fukuoka branch starting next month. (company's decision)","I've decided to set aside time to read every night. (my own decision)","It's been decided that I'll be in charge of chairing the meeting. (superiors' decision)"],"t":"～ことになる・～ことにする","p":"dictionary form ＋ ことになる (external decision) ／ ことにする (self decision)"},"n3-51":{"cat":"Others","ex":"\"It seems / it looks like ~.\" A guess based on the speaker's own observation. 「ようだ」 is more formal, while 「みたいだ」 is colloquial.","eg":["It seems no one is home in the room next door.","It looks like it's raining outside.","The new boss seems to be a strict person."],"t":"～ようだ・～みたいだ","p":"plain form ＋ ようだ (more formal) ／ みたいだ (colloquial)"},"n3-52":{"cat":"Others","ex":"Two uses: (1) \"apparently / I hear that ~\" (an inference based on hearsay or information from an outside source); (2) \"typical of / just like ~\" (attached to a noun to say something is very characteristic of it).","eg":["Apparently the temperature will drop starting next week.","His remark is so typical of him.","Apparently that company is going to abolish remote work next month."],"t":"～らしい","p":"plain form ＋ らしい"},"n3-53":{"cat":"Others","ex":"\"In order to ~ / for the sake of ~.\" With a dictionary-form verb or 「名詞の」 it expresses an intentional purpose; it can also express a reason/cause. The subject typically controls the action.","eg":["To get a qualification, I'm taking a correspondence course.","For my family's sake, I try to spend every weekend at home.","To improve my health-checkup numbers, I've started going to the gym."],"t":"～ために","p":"dictionary form／noun ＋ の ＋ ために"},"n3-54":{"cat":"Others","ex":"\"So that ~ / in order to be able to ~.\" A way of expressing purpose that pairs with non-volitional verbs, potential forms, or negatives (unlike 「ために」, which takes volitional verbs).","eg":["So that I don't forget anything, I pack my things the day before.","So that the people in back could hear too, I used a microphone.","So that I'd make the last flight, I headed to the airport early."],"t":"～ように","p":"dictionary form／nai-form ＋ ように"},"n3-55":{"cat":"Others","ex":"\"(tell someone) to ~.\" Used with verbs like 「言う」 to indirectly report an instruction, request, or warning given to someone.","eg":["The teacher warned us again and again to be on time.","The doctor told me to cut down on salt.","The client drove home the point that we must absolutely meet the deadline."],"t":"～ようにと","p":"dictionary form／nai-form ＋ ようにと ＋ 言う, etc."},"n3-56":{"cat":"Others","ex":"\"Because ~ / owing to the fact that ~.\" Used to explain the origin of a name or the grounds for a judgment/conclusion.","eg":["Because hot springs bubble up here, this area is known as a tourist destination.","Because he's always smiling, he's called \"the Sun.\"","Because the shape of the mountain resembles a pot, it was named \"Nabeyama\" (Pot Mountain)."],"t":"～ことから","p":"plain form ＋ ことから"},"n3-57":{"cat":"Others","ex":"\"Every time ~ / whenever ~.\" It indicates that each time an action or event occurs, something else regularly happens along with it.","eg":["Every time I look at this photo, I remember my student days.","Every time I go on a business trip, I buy souvenirs to bring home.","Every time the seasons change, I tend to fall ill."],"t":"～たびに","p":"dictionary form ＋ たびに／noun ＋ の ＋ たびに"},"n3-58":{"cat":"Others","ex":"\"Centering on ~\" / \"with ~ at the center.\" Indicates the core, focus, or central point around which something else spreads, develops, or is organized. Attaches to a noun.","eg":["A shopping street spreads out with the station at its center.","The team came together, centered on its leader.","This campaign will be developed with women in their twenties as the main focus."],"t":"～を中心に","p":"noun ＋ を中心に（して）"},"n3-59":{"cat":"Others","ex":"\"Through ~\" / \"by means of ~\" / \"via ~.\" Indicates a means, medium, or intermediary; can also express something continuing throughout an entire period. Attaches to a noun. 「を通じて」 tends to be a bit more formal/written, while 「を通して」 emphasizes actively using something as a channel, but the two are largely interchangeable.","eg":["Through social media, I reunited with an old friend.","It is a region where the humidity stays high throughout the year.","Through a consultant, I was introduced to a business client."],"t":"～を通じて・～を通して","p":"noun ＋ を通じて／を通して"},"n3-60":{"cat":"Others","ex":"\"Based on ~\" / \"on the basis of ~.\" Indicates the grounds or foundation on which an action is taken or a judgment is made. Use 「に基づいて」 before a verb/clause and 「に基づく＋noun」 to modify a following noun. Attaches to a noun.","eg":["Based on the experiment results, I wrote the paper.","I presented an improvement plan based on the questionnaire.","Based on past precedents, the lawyer devised a strategy."],"t":"～に基づいて・～に基づく","p":"noun ＋ に基づいて／に基づく ＋ noun"},"n3-61":{"cat":"Others","ex":"\"Should ~\" / \"ought to ~\" (and 「べきではない」 = \"should not ~\"). Expresses a moral, social, or common-sense obligation about what is or isn't the right thing to do. Attaches to the dictionary form; note the special form 「する」→「すべき」 (「するべき」 is also accepted).","eg":["A manager should first listen to the voices of the front line.","You shouldn't say such irresponsible things.","You should check every detail down to the fine print before signing a contract."],"t":"～べきだ・～べきではない","p":"dictionary form ＋ べきだ (する→すべきだ)"},"n3-62":{"cat":"Others","ex":"\"Because ~\" / \"since ~.\" Gives a reason, but with a nuance of making an excuse or justifying oneself, often for something unfortunate or apologetic. Attaches to the plain form. 「もので」 is a softer, more colloquial variant of 「ものだから」.","eg":["Because the road was congested, I ended up being late. (making an excuse)","Since something urgent came up, please allow me to be absent.","Because the train service was suspended, I switched to the bus."],"t":"～ものだから・～もので","p":"plain form ＋ ものだから／もので"},"n3-63":{"cat":"Others","ex":"\"Even ~\" / \"not even ~.\" Emphasizes an extreme example, implying that if even this (unexpected) case holds, other cases certainly do too. Attaches to a noun (which may take a particle, e.g. 「にさえ」).","eg":["I'm so busy I don't even have time to eat.","Not to mention kanji, I can't even read hiragana yet.","I haven't even told my family that I'm changing jobs yet."],"t":"～さえ","p":"noun ＋ さえ"},"n3-64":{"cat":"Others","ex":"\"It is precisely ~\" / \"~ is the very thing.\" Emphasizes and singles out the preceding word as the true or definitive one. Attaches to a noun.","eg":["This year for sure, I want to pass the exam.","The pleasure is all mine; I look forward to working with you from now on.","Now is precisely the chance to take on something new."],"t":"～こそ","p":"noun ＋ こそ"},"n3-65":{"cat":"Appearance & Tendency","ex":"\"Looks like ~\" / \"seems ~.\" An intuitive judgment based on outward appearance or the way something looks. Attaches to the い-adjective stem, な-adjective stem, or verb ます-stem. Note: 「いい」→「よさそう」 and 「ない」→「なさそう」.","eg":["This cake looks really delicious.","The clouds look heavy, so it seems like it's going to rain.","She is operating the screen looking very busy."],"t":"～そうだ（様態）","p":"i-adjective stem／na-adjective stem／masu-form ＋ そうだ"},"n3-66":{"cat":"Appearance & Tendency","ex":"\"I hear that ~\" / \"they say ~.\" Reports hearsay — information obtained from some other source (news, another person, etc.). Attaches to the plain form. Distinguish from the 様態 (looks-like) 「そうだ」, which attaches to stems, not the plain form.","eg":["According to the forecast, they say it will get cold over the weekend.","I hear that new bookstore has a good selection.","I hear the work-from-home system will be expanded starting next term."],"t":"～そうだ（伝聞)","p":"plain form ＋ そうだ"},"n3-67":{"cat":"Others","ex":"\"~ come to / begin to\" and \"~ go on / continue to.\" Expresses the direction of an action (toward or away from the speaker) or a trend of change over time: 「てくる」 for change up to the present, 「ていく」 for change continuing into the future. Attaches to the て-form.","eg":["Autumn has come, and the mornings and evenings have grown cold. (change continuing up to now)","I intend to keep making steady efforts from now on.","Over the past few years, online meetings have been increasing."],"t":"～てくる・～ていく","p":"te-form ＋ くる／te-form ＋ いく"},"n3-68":{"cat":"Others","ex":"「ている」 = \"be doing / be in a state.\" 「てある」 = \"has been done (by someone) and the result remains\" (typically with transitive verbs). 「ておく」 = \"do something in advance / in preparation.\" All attach to the て-form.","eg":["The air conditioner is on. (state)","The reference materials have been placed in the meeting room.","I'll print out the materials for tomorrow's presentation in advance."],"t":"～ている・～てある・～ておく","p":"te-form ＋ いる／te-form ＋ ある／te-form ＋ おく"},"n3-69":{"cat":"Others","ex":"Giving-and-receiving verbs. 「てもらう」 = \"have/get someone to do (for me).\" 「てあげる」 = \"do (something) for someone else.\" 「てくれる」 = \"someone does (something) for me.\" All attach to the て-form; the direction of the favor depends on which verb is used.","eg":["I had a colleague check the documents for me.","My father bought me a watch for my birthday.","I taught my younger sister her schoolwork."],"t":"～てもらう・～てあげる・～てくれる","p":"te-form ＋ もらう／あげる／くれる"},"n3-70":{"cat":"Others","ex":"Causative: \"make/let someone do ~.\" Expresses either forcing someone to do something or permitting them to do it. Formation: Group-1 (五段) verbs change the final syllable to the あ-row + せる; Group-2 (一段) verbs take させる; 「する」→「させる」, 「くる」→「こさせる」.","eg":["The mother made her child finish the homework.","The store manager had the staff take charge of the closing work.","The leader had the members divide up the roles."],"t":"～させる（使役）","p":"verb causative form: godan → a-sound stem ＋ せる, ichidan → させる"},"n3-71":{"cat":"Others","ex":"Passive: \"be ~ed.\" Expresses being on the receiving end of another's action; often carries a nuance of nuisance or being adversely affected (the \"suffering passive\"). Formation: Group-1 (五段) verbs change the final syllable to the あ-row + れる; Group-2 (一段) verbs take られる; 「する」→「される」, 「くる」→「こられる」.","eg":["At the concert venue, the person next to me bumped into my shoulder.","My idea was praised by my boss.","Someone stepped on my foot on the commuter train, and it put me in a bad mood from the morning."],"t":"～（ら）れる（受身）","p":"verb passive form: godan → a-row ＋ れる, ichidan → られる"},"n3-72":{"cat":"Others","ex":"Causative-passive: \"be made to ~.\" Expresses being forced to do something against one's will. Formation: Group-1 (五段) verbs change the final syllable to the あ-row + される; Group-2 (一段) verbs take させられる; 「する」→「させられる」, 「くる」→「こさせられる」.","eg":["I was made to eat celery, which I hate.","I'm made to work overtime almost every week.","I was made to give a speech at the welcome-and-farewell party."],"t":"～させられる（使役受身）","p":"verb causative-passive form: godan → a-row ＋ される, ichidan → させられる"},"n3-73":{"cat":"Condition & Hypothesis","ex":"\"Even if ~\" / \"even though ~.\" Expresses a concessive condition: the result holds regardless of the preceding circumstance. Attaches to the て-form (「でも」 after nouns/な-adjectives). Often paired with question words (どんなに, 何度) for \"no matter how ~.\"","eg":["Even if a typhoon comes, we'll depart as scheduled.","No matter how many times I check, I can't find the mistake.","No matter how busy I am, I never skip breakfast."],"t":"～ても","p":"te-form ＋ も／でも"},"n3-74":{"cat":"Others","ex":"\"Have (once) done ~\" / \"there was a time when ~.\" Expresses a past experience. Attaches to the た-form of a verb.","eg":["I have tried paragliding.","Have you ever been to Aoshima in Miyazaki?","I have lived alone overseas."],"t":"～ことがある（経験）","p":"ta-form ＋ ことがある"},"n3-75":{"cat":"Others","ex":"\"Be able to ~\" / \"can ~.\" Expresses ability or possibility. Attaches to the dictionary form of a verb. It is a more formal equivalent of the potential verb form.","eg":["I can negotiate in business-level English.","You can enter this exhibition without a prior reservation.","It has become possible to apply online."],"t":"～ことができる","p":"dictionary form ＋ ことができる"},"n3-76":{"cat":"Assertion & Emphasis","ex":"\"So ~ that I can't stand it\" / \"unbearably ~.\" Expresses a feeling, sensation, or emotion so strong that it can't be controlled. Attaches to the て-form of adjectives/verbs. 「てたまらない」 and 「てしかたがない」 tend to describe physical or emotional feelings, while 「てならない」 is a bit more literary and often used with spontaneous feelings/thoughts (worry, sadness, etc.).","eg":["A room without air conditioning is unbearably hot.","I can't stop worrying about the pass/fail announcement.","I can't help worrying about my daughter, who is studying abroad."],"t":"～てたまらない・～てしかたがない・～てならない","p":"te-form ＋ たまらない／しかたがない／ならない"},"n3-77":{"cat":"Others","ex":"\"In accordance with ~\" / \"just as ~.\" Indicates doing something following a certain method, model, or instruction. Use 「どおりに」 after a noun (「計画どおりに」) and 「とおりに」 after a verb in the dictionary or た-form (「教わったとおりに」).","eg":["When I made it exactly according to the recipe, it came out with an authentic taste.","It is progressing according to plan.","I wrote the report just as my senior colleague taught me."],"t":"～どおりに・～とおりに","p":"noun ＋ どおりに／dictionary form・ta-form ＋ とおりに"},"n3-78":{"cat":"Others","ex":"\"Was it ~ again?\" / \"~, right?\" A colloquial ending used when trying to recall or confirm something one is not quite sure of from memory. Attaches to the plain form (often 「だっけ」 after nouns/な-adjectives).","eg":["What time does tomorrow's meeting start again?","Have I already read that book, or...?","His birthday is next week, right?"],"t":"～っけ","p":"plain form ＋ っけ (colloquial)"},"n3-79":{"cat":"Comparison & Degree","ex":"\"On the other hand ~\" / \"while (conversely) ~.\" Presents a contrasting or opposite side of the same thing, pairing a positive point with a negative one (or vice versa). Attaches to the plain form (な-adjectives take 「な反面」, nouns take 「である反面」).","eg":["He is fast at his work, but on the other hand he makes a lot of small mistakes.","The city is convenient, but on the other hand human relationships are shallow.","This software is rich in features, but on the other hand it is complicated to operate."],"t":"～反面","p":"plain form ＋ 反面"}};
const N2_EN = {"n2-1":{"cat":"Time / Change","ex":"\"To be gradually ~ing.\" Expresses an ongoing process of change moving steadily in one direction. Written/formal register. Attaches to the ます-stem of a verb.","eg":["The Earth's average temperature is gradually rising.","Traditional craft techniques are gradually being lost.","The vacant-house problem in urban areas is gradually worsening."],"t":"～つつある","p":"masu-form (stem) ＋ つつある"},"n2-2":{"cat":"Time / Change","ex":"\"Keeps ~ing / only gets more and more ~.\" Emphasizes that a state changes in one single direction with no reversal. Often carries a negative nuance, but not always (e.g. 「上達するばかりだ」 = keeps getting better and better). Attaches to the dictionary form of a verb.","eg":["My stamina just keeps declining.","The workload only keeps increasing.","Apartment prices in the city center just keep rising."],"t":"～ばかりだ（変化）","p":"dictionary form ＋ ばかりだ"},"n2-3":{"cat":"Time / Change","ex":"\"From ~ to ~ (over a span or range).\" Indicates an approximate span or range from one point to another, in time or space. Used as 「Noun から Noun にかけて」.","eg":["From around March to April, cherry blossoms bloom all across the country.","From the Kanto region up through Tohoku, tomorrow's weather is expected to turn stormy.","From evening into the night, temperatures are expected to drop nationwide."],"t":"～にかけて","p":"noun ＋ から ＋ noun ＋ にかけて"},"n2-4":{"cat":"Time / Change","ex":"\"After ~ / as the result of ~ (finally).\" Indicates that a result is reached after much effort, struggle, or a long process. Used as 「Noun の末（に）」 or 「た-form ＋末（に）」.","eg":["After several hours of discussion, a conclusion was finally reached.","After agonizing over it endlessly, I made up my mind to study abroad.","After talking it over as a family, we decided to move out to the suburbs."],"t":"～末（に）","p":"noun ＋ の ＋ 末（に）／ta-form ＋ 末（に）"},"n2-5":{"cat":"Time / Change","ex":"\"The moment ~ / as soon as ~.\" The second event happens immediately, right after the first action is completed. Attaches to the た-form of a verb. Often the second event is unexpected or beyond one's control.","eg":["The moment I opened the front door, my dog came leaping at me.","The moment I took the medicine, I was hit by overwhelming drowsiness.","The moment I stepped out of the station, I got caught in a violent evening downpour."],"t":"～たとたん（に）","p":"ta-form ＋ とたん（に）"},"n2-6":{"cat":"Time / Change","ex":"\"As soon as ~ / the moment ~ is done.\" The second action is carried out immediately upon completion of the first. Attaches to the ます-stem of a verb. Used for future actions; the following clause cannot be past tense.","eg":["We will contact you as soon as the package arrives.","Let's set off as soon as the preparations are ready.","As soon as the contract arrives, I'll sign it and send it back."],"t":"～次第","p":"masu-form (stem) ＋ 次第"},"n2-7":{"cat":"Time / Change","ex":"\"Ever since ~.\" Indicates that a state has continued from the time of some event up to the present. Attaches to the て-form of a verb. Used for events with lasting effects, not one-time short events.","eg":["Ever since I moved to this neighborhood, morning jogging has become part of my daily routine.","Ever since I graduated from university, I haven't seen my classmates even once.","Ever since remote work was introduced, my commute time has become zero."],"t":"～て以来","p":"te-form ＋ 以来"},"n2-8":{"cat":"Cause / Reason","ex":"\"Now that ~ / since ~.\" Expresses that, given the situation in the first clause, a certain resolve or obligation naturally follows. Stronger and more emphatic than 「以上」, stressing determination. Attaches to the plain form.","eg":["Now that I've taken on the project, I'll see it through to the end responsibly.","Since I'm going to study abroad, I want to deeply learn the local culture.","Now that I'm starting a business, I need to be prepared to bring others on board."],"t":"～からには","p":"plain form ＋ からには"},"n2-9":{"cat":"Cause / Reason","ex":"\"It is precisely because ~ that ~.\" Emphasizes that the stated reason is the very, specific cause of the result. Attaches to the plain form.","eg":["It's precisely because we're family that I say even the harsh things.","It's precisely because I built it up every day that I passed this time.","It's precisely because the ingredients are good that simple cooking tastes best."],"t":"～からこそ","p":"plain form ＋ からこそ"},"n2-10":{"cat":"Contrast / Concession","ex":"\"Despite ~ / in spite of ~.\" A written, formal concessive expression with a fairly strong tone, indicating that a result runs contrary to what the first clause would lead you to expect. Attaches to the plain form (or a noun).","eg":["Despite having checked it many times, I made the same mistake again.","In spite of the rain, a large crowd of visitors gathered.","Despite it being a weekday, there was a line at the popular bakery."],"t":"～にもかかわらず","p":"plain form ＋ にもかかわらず"},"n2-11":{"cat":"Contrast / Concession","ex":"\"Although ~, but ~.\" Acknowledges the fact in the first clause, but the result falls short of, or runs counter to, what one would expect. Attaches to the plain form.","eg":["Although I bought a ticket, in the end I couldn't go.","Although I received an explanation, I still don't really understand how to operate it.","Although I joined the gym, I've been so busy I've only gone once."],"t":"～ものの","p":"plain form ＋ ものの"},"n2-12":{"cat":"Contrast / Concession","ex":"\"That said ~ / even though it's said to be ~.\" Concedes the first clause as true, but points out that it doesn't fully hold or apply. Attaches to the plain form (or a noun).","eg":["It may be spring, but mornings and evenings are still chilly.","He may be a child, but there are still jokes that are okay to make and jokes that aren't.","Used to it though I am, I still get nervous before a presentation."],"t":"～とはいえ","p":"plain form ＋ とはいえ"},"n2-13":{"cat":"Contrast / Concession","ex":"\"Even though ~ / despite ~ (and yet).\" Points out a contradiction between two facts about the same person, carrying a tone of blame, criticism, or dissatisfaction. Attaches to the plain form.","eg":["Even though he knows, he won't tell me.","He does nothing himself, yet he's always bossing others around.","Even though he can't cook, he complains about the seasoning."],"t":"～くせに","p":"plain form ＋ くせに"},"n2-14":{"cat":"Contrast / Concession","ex":"\"On the one hand ~, on the other hand ~ / while ~.\" Presents two contrasting or coexisting aspects of a situation. Attaches to the plain form.","eg":["While the urban population is increasing, the rural population continues to decline.","While work keeps me busy, I also want to treasure time with my family.","While things are becoming more convenient, there are also things being lost."],"t":"～一方（で）","p":"plain form ＋ 一方（で）"},"n2-15":{"cat":"Contrast / Concession","ex":"\"Even if ~ / even granting that ~.\" Concedes a point for the sake of argument, yet the conclusion remains unchanged. Attaches to the plain form. When repeated (「A にしても B にしても」) it means \"whether A or B.\"","eg":["Even if you were busy, you could at least have dropped a quick message.","Even if it was a joke, it's not the sort of thing you should say.","Whether by train or by bus, the morning hours are crowded."],"t":"～にしても","p":"plain form ＋ にしても"},"n2-16":{"cat":"Contrast / Concession","ex":"\"While ~ / even though ~.\" A written expression indicating that one does (or fails to do) something even while fully aware of the contrary. Attaches to the ます-stem of a verb.","eg":["Even though I know it's bad for my health, I can't stop staying up late.","Even while feeling apologetic, I ended up putting off replying.","Even though I'd been told it was urgent, I ended up prioritizing other work anyway."],"t":"～つつ（も）","p":"masu-form (stem) ＋ つつ（も）"},"n2-17":{"cat":"Contrast / Concession","ex":"\"Although ~ / while ~.\" Expresses a contrast between two facts. Also common in speech. Attaches to the ます-stem of a verb, or to a noun or adjective.","eg":["Regrettably, you were not selected this time.","Small though it is, he has set up his own office.","Cramped though it is, it's a room that's comfortable to live in."],"t":"～ながら（も）","p":"masu-form (stem) ＋ ながら（も）／noun・adjective ＋ ながら（も）"},"n2-18":{"cat":"Condition / Hypothesis","ex":"\"If (only) one could ~ (but in reality one can't).\" Expresses a challenge or a wish about something that is in fact impossible or very difficult. Attaches to the dictionary form of a potential verb.","eg":["If you think you can do it, then go ahead and try it (I bet you can't).","If only I could go back, I'd love to return to my high school days.","If only I could, I'd take that pain in your place."],"t":"～ものなら","p":"potential-verb dictionary form ＋ ものなら"},"n2-19":{"cat":"Condition / Hypothesis","ex":"\"Unless ~ (you can't ~).\" Indicates a necessary condition: without doing the first thing, the result in the second clause cannot be achieved. Attaches to the ない-form of a verb; the following clause is typically negative.","eg":["Unless you actually try it out, you can't tell whether it's any good.","Unless you check with the person themselves, you can't judge whether it's true.","Unless you actually visit the place, you won't understand its true charm."],"t":"～ないことには","p":"nai-form ＋ ことには"},"n2-20":{"cat":"Scope / Limitation","ex":"\"Not limited to ~ / not only ~.\" Indicates that the scope extends beyond just the stated item to a wider range. Attaches to a noun.","eg":["Not just among young people, smartphones have spread to the elderly as well.","Not only in Japan, but across all of Asia the birthrate is declining.","Not just on weekends, the number of companies allowing remote work on weekdays too has increased."],"t":"～に限らず","p":"noun ＋ に限らず"},"n2-21":{"cat":"Scope / Limitation","ex":"\"Regardless of ~ / irrespective of ~.\" Indicates that something is not restricted by the stated condition. Attaches to a noun (often a noun expressing a range of possibilities, such as age, gender, or presence/absence).","eg":["Regardless of age, anyone is welcome to take part.","Regardless of whether you have experience or not, we welcome your application.","Regardless of nationality, anyone can participate in this event."],"t":"～を問わず","p":"noun ＋ を問わず"},"n2-22":{"cat":"Scope / Limitation","ex":"\"Over (a span of) ~ / spanning ~.\" Indicates that something extends over a wide range or a long period of time. Attaches to a noun (usually one expressing a length of time or an extent).","eg":["An international conference was held over the course of three days.","A power outage occurred over a wide area.","For over 20 years, I have continued research in the same field."],"t":"～にわたって","p":"noun ＋ にわたって"},"n2-23":{"cat":"Scope / Limitation","ex":"\"Based on ~ / according to ~.\" Indicates that something is created or done using the preceding noun as the basis or source material.","eg":["A movie based on a true story was released.","Based on the customer survey, we improved our service.","We forecast this term's demand based on past data."],"t":"～をもとに（して）","p":"noun ＋ をもとに（して）"},"n2-24":{"cat":"Scope / Limitation","ex":"\"According to ~ / in accordance with ~.\" Indicates that something changes or is adjusted in response to varying circumstances (each case differs depending on the noun).","eg":["The bonus is determined according to your results.","We respond flexibly according to the situation.","We change the menu according to the season."],"t":"～に応じて","p":"noun ＋ に応じて"},"n2-25":{"cat":"Degree / Emphasis","ex":"\"Far from ~ / let alone ~.\" Used to deny the first item and show that reality is the opposite of, or far removed from, what was expected.","eg":["Far from being easy, it was harder than I imagined.","Far from being thanked, I was actually complained at.","Far from cooling down, midsummer weather has continued even into September."],"t":"～どころか","p":"plain form ＋ どころか"},"n2-26":{"cat":"Degree / Emphasis","ex":"\"Not only ~ but also ~.\" Adds a further, often more striking, item on top of the first.","eg":["Not only Japanese, but he can also speak Chinese fluently.","Not only was he late, but he also forgot to bring the materials.","Not only is he good at his job, but he is also well respected."],"t":"～ばかりか・ばかりでなく","p":"plain form ＋ ばかりか"},"n2-27":{"cat":"Degree / Emphasis","ex":"\"Not only ~ (but also).\" A written, formal expression meaning that something applies not just to the first item but to a wider range.","eg":["It is highly regarded not only domestically but also in overseas markets.","It has won support not only from the young but from a wide range of generations.","The number of users of this app is surging not only in Japan but also in Southeast Asia."],"t":"～のみならず","p":"plain form ＋ のみならず"},"n2-28":{"cat":"Degree / Emphasis","ex":"\"~ needless to say / of course ~.\" The first item is taken for granted, and the point is that the second (often less obvious) item also holds true.","eg":["English of course, but she can also hold everyday conversations in Spanish.","It's a theme park popular with adults, of course, but with children too.","It's an apartment that comes with furniture, of course, and even home appliances."],"t":"～はもちろん","p":"noun ＋ はもちろん"},"n2-29":{"cat":"Degree / Emphasis","ex":"\"No more than ~ / merely ~.\" Indicates that something is only that and nothing more, downplaying its degree or importance.","eg":["This is no more than a personal opinion.","He is still merely a new employee.","This figure is no more than the tip of the iceberg."],"t":"～にすぎない","p":"plain form ＋ にすぎない"},"n2-30":{"cat":"Degree / Emphasis","ex":"\"Just as you'd expect from ~ / it lives up to its reputation.\" Expresses admiration that the result matches the high standing, effort, or experience behind it.","eg":["As you'd expect from a first-class hotel; the service is on another level.","It shows he trained for ten years; his cooking skills are outstanding.","As you'd expect with 300,000 participants, it was a marathon well worth watching."],"t":"～だけのことはある","p":"plain form ＋ だけのことはある"},"n2-31":{"cat":"Degree / Emphasis","ex":"\"Worthy of ~ / deserves ~.\" Indicates that something has enough value to merit the action or evaluation. A written, formal expression.","eg":["This work is worthy of an international award.","His devoted attitude deserves respect.","This historic townscape is worth visiting at least once."],"t":"～に値する","p":"noun ＋ に値する／dictionary form ＋ に値する"},"n2-32":{"cat":"Topic / Evaluation","ex":"\"Now that ~ / given that ~ (one should~).\" Expresses the responsibility or obligation that comes with a given position or status.","eg":["Now that you are a teacher, you must set an example for your students.","Now that you are a working member of society, you should follow society's rules.","Now that he is the branch manager, he is required to meet the sales targets."],"t":"～上は","p":"plain form ＋ 上は"},"n2-33":{"cat":"Topic / Evaluation","ex":"\"Not only ~ but also ~ / on top of ~.\" Adds a further quality on top of one that already exists (both usually of the same positive or negative tone).","eg":["This restaurant is reasonably priced, and on top of that the food quality is high.","He has a sharp mind, and on top of that his athletic ability is outstanding.","This cafe is close to the station, and on top of that the Wi-Fi is fast."],"t":"～上に","p":"plain form ＋ 上に"},"n2-34":{"cat":"Topic / Evaluation","ex":"\"Because it's ~ (the kind of person/thing it is), ~.\" Makes a prediction based on what one knows about a person's character or nature.","eg":["Being the meticulous person he is, he surely won't be late.","Being the optimist that person is, they'll surely bounce back quickly.","Being the foodie my mother is, she has surely already researched a delicious restaurant."],"t":"～ことだから","p":"noun の ＋ ことだから"},"n2-35":{"cat":"Sentence-ending Expressions","ex":"\"Cannot help but ~ / have no choice but to ~.\" There is no other option, so one is forced to do it. Note the irregular form: する becomes せざるを得ない.","eg":["Since it's my boss's decision, I have no choice but to comply.","Since all the evidence is in place, I have no choice but to admit it.","I missed the last train, so I had no choice but to stay at a hotel near the station."],"t":"～ざるを得ない","p":"nai-form (drop ない) ＋ ざるを得ない"},"n2-36":{"cat":"Sentence-ending Expressions","ex":"\"Can't help ~ing / can't resist ~.\" Expresses an emotion or urge one cannot control. Note the irregular form: する becomes せずにはいられない.","eg":["Whenever I watch that movie, I can't help crying.","Faced with freshly baked bread, I can't help but want to eat it.","Whenever I see beautiful scenery, I can't help taking a photo."],"t":"～ないではいられない・ずにはいられない","p":"nai-form (drop ない) ＋ ないではいられない／ずにはいられない"},"n2-37":{"cat":"Sentence-ending Expressions","ex":"\"Find it hard to ~ / be unable to ~.\" A polite way to decline or to express difficulty in doing something.","eg":["I'm afraid I'm unable to answer that request.","I find it hard to agree with that conclusion.","We are very sorry, but we are unable to accept same-day delivery."],"t":"～かねる","p":"masu-form (drop ます) ＋ かねる"},"n2-38":{"cat":"Sentence-ending Expressions","ex":"\"Might well ~ / could end up ~ (something bad).\" Indicates that an undesirable outcome is possible.","eg":["If we keep neglecting countermeasures, this could well develop into a major accident.","If you keep overdoing it, you might end up ruining your health.","Continued lack of sleep could lead to errors in judgment."],"t":"～かねない","p":"masu-form (drop ます) ＋ かねない"},"n2-39":{"cat":"Sentence-ending Expressions","ex":"\"Can ~ / is possible ~ (得る) / cannot ~ / is impossible (得ない).\" Expresses possibility. The affirmative form reads either \"uru\" or \"eru\"; the negative is always \"enai.\"","eg":["Realistically, such a thing is impossible.","It's a familiar problem that can happen to anyone.","An earthquake can strike at any time, so let's stay disaster-conscious."],"t":"～得る・得ない","p":"masu-form (drop ます) ＋ 得る（うる／える）"},"n2-40":{"cat":"Sentence-ending Expressions","ex":"\"There's no way ~ / absolutely couldn't ~.\" A colloquial expression with a strong tone, flatly denying a possibility.","eg":["There's no way I'll pass such a high-level exam on the first try.","There's no way you can get a reservation at this time of year.","There's no way I can finish all of it in a single day before the deadline."],"t":"～っこない","p":"masu-form (drop ます) ＋ っこない"},"n2-41":{"cat":"Sentence-ending Expressions","ex":"\"Must be ~ / surely ~.\" A strong inference or conviction based on evidence.","eg":["There's no way he'd overlook this mistake. He must have noticed it.","Doing this amount of work alone must be tough.","With a line this long, this restaurant must be delicious."],"t":"～に違いない","p":"plain form ＋ に違いない"},"n2-42":{"cat":"Sentence-ending Expressions","ex":"\"Must surely be ~ / of course it's ~.\" A colloquial expression carrying a subjective, confident assertion.","eg":["If you use this ingredient, it's bound to be delicious.","A deal that good has to be a lie.","After practicing this much, it's bound to go well."],"t":"～に決まっている","p":"plain form ＋ に決まっている"},"n2-43":{"cat":"Sentence-ending Expressions","ex":"\"Without a doubt ~ / must undoubtedly be ~.\" A written expression, more formal than 「に違いない」.","eg":["What led this project to success was, without a doubt, his skill.","This result is without a doubt the fruit of everyone's effort.","This handwriting is without a doubt my grandfather's."],"t":"～に相違ない","p":"plain form ＋ に相違ない"},"n2-44":{"cat":"Sentence-ending Expressions","ex":"\"How ~ it is! / ~ indeed.\" Used to express admiration, emotion, or heartfelt reflection about a general truth.","eg":["How quickly time really does pass!","I used to play in this river a lot when I was a child.","A human life is such a fleeting thing."],"t":"～ものだ (exclamation)","p":"plain form ＋ ものだ"},"n2-45":{"cat":"Other","ex":"\"in the manner of ~\" / \"after an interval of ~.\" Attaches to a noun. (1) With action/manner nouns it describes the way something is done. (2) With a period of time it means \"for the first time in ~ / after ~ have passed.\"","eg":["From the way he spoke, I sensed his confidence.","I visited my alma mater for the first time in 5 years.","I was reunited with my high school classmates for the first time in 10 years."],"t":"～ぶり","p":"noun ＋ ぶり"},"n2-46":{"cat":"Other","ex":"\"hard to ~ / difficult to bring oneself to ~.\" Expresses that something is psychologically/emotionally difficult to do (not physically impossible). Attaches to the verb stem (masu-form minus ます). Literary/written style.","eg":["Even now, I find that action of his hard to understand.","It was an almost unbelievably lucky event.","This result is hard to accept, but I have no choice but to acknowledge it as reality."],"t":"～がたい","p":"masu-form (drop ます) ＋ がたい"},"n2-47":{"cat":"Other","ex":"\"half-done / in the middle of ~-ing.\" Attaches to the verb stem (masu-form minus ます). Indicates an action that is partway through or unfinished; use 「かけの」 before a noun.","eg":["Half-read novels are piled up on the bookshelf.","He started to say something, then stopped partway.","Leaving my half-eaten bread on the desk, I answered the phone."],"t":"～かける・かけの","p":"masu-form (drop ます) ＋ かける／かけの"},"n2-48":{"cat":"Other","ex":"\"without ~-ing (yet did ~).\" Attaches to the dictionary form. Indicates that the main action was carried out without a certain accompanying action taking place. Literary/written style.","eg":["Without stopping even once, I ran all the way to the finish line.","Without giving up, I kept challenging myself to the very end.","Without taking a break even on rainy days, I jog in the park every morning."],"t":"～ことなく","p":"dictionary form ＋ ことなく"},"n2-49":{"cat":"Other","ex":"\"there is no way to ~ / cannot possibly ~.\" Attaches to the verb stem (masu-form minus ます). Means you want to do something but there is no means or method available to do it.","eg":["I don't know the contact details, so there's no way to get in touch.","No evidence remains, so there's no way to explain it.","There are no clues at all, so there's no way to investigate it."],"t":"～ようがない・ようもない","p":"masu-form (drop ます) ＋ ようがない"},"n2-50":{"cat":"Other","ex":"\"along with ~ / as ~.\" Indicates that as one change occurs, another change accompanies it. Attaches to a noun (名詞＋に伴って) or to a verb via のに伴って.","eg":["Along with the increase in population, the housing shortage in urban areas grew serious.","As the economy developed, the burden on the environment also increased.","As remote work has spread, the number of people choosing to move to rural areas is rising."],"t":"～に伴って・に伴い","p":"noun ＋ に伴って／dictionary form ＋ のに伴って"},"n2-51":{"cat":"Other","ex":"\"on the occasion of ~ / when ~.\" Attaches to the dictionary form or to a noun with の. More formal than 「時」; common in polite or official contexts.","eg":["When you leave, please take care not to forget your belongings.","When you apply, please bring your identification.","Should there be any deficiencies in the documents, we will contact you promptly."],"t":"～際（に）","p":"dictionary form ・ noun の ＋ 際（に）"},"n2-52":{"cat":"Other","ex":"\"judging from ~ / from the standpoint of ~.\" Attaches to a noun. Indicates the viewpoint or basis from which a judgment is made.","eg":["From a parent's point of view, worrying about a child's future is only natural.","Judging from his expression, he seems to be hiding something.","Judging from the budget, this project is quite tight."],"t":"～からすると・からすれば","p":"noun ＋ からすると"},"n2-53":{"cat":"Other","ex":"\"when it comes to ~ (one excels).\" Attaches to a noun. Emphasizes that someone's ability is outstanding in one particular area or field.","eg":["When it comes to Japanese cuisine, no one can surpass her.","When it comes to memory, I won't lose to anyone in my cohort.","When it comes to debates about speed, he is the best in the company."],"t":"～にかけては","p":"noun ＋ にかけては"},"n2-54":{"cat":"Other","ex":"\"as ~ / in proportion as ~.\" Attaches to the dictionary form or a noun. Indicates that two things change together, gradually and in tandem.","eg":["As time passed, the pain eased.","As the season progressed, the temperature gap between morning and night grew larger.","As AI has evolved, the way we work has changed too."],"t":"～につれて","p":"dictionary form ・ noun ＋ につれて"},"n2-55":{"cat":"Concession / Contrast","ex":"\"whether ~ or ~ / even if ~.\" Attaches to the plain form. Lists multiple cases and states that the conclusion is the same regardless of which applies. More formal/written than 「にしても」.","eg":["Whether you agree or disagree, you should express your opinion honestly.","Whatever the reason may be, absence without notice is not permitted.","Whether by train or by bus, it's best to avoid rush hour."],"t":"～にしろ・～にせよ","p":"plain form ＋ にしろ／にせよ"},"n2-56":{"cat":"Degree / Emphasis","ex":"\"is nothing other than ~ / is precisely ~.\" Attaches to a noun or the plain form. Strongly asserts the cause or essential nature of something. Literary/written style.","eg":["The success was nothing other than the accumulation of daily effort.","She shed tears for no reason other than that she was happy.","The fact that this town's scenery has been preserved is thanks to nothing other than the residents' efforts."],"t":"～にほかならない","p":"noun ＋ にほかならない／plain form ＋ にほかならない"},"n2-57":{"cat":"Sentence-ending Expressions","ex":"\"I will not ~ / probably won't ~.\" (1) Negative volition (a firm resolve not to do something). (2) Negative conjecture (surely won't). For godan verbs, attach まい to the dictionary form; for ichidan, カ変, and サ変 verbs, attach it to the masu-stem. Literary/written style.","eg":["I swore to myself that I would never make that kind of mistake again.","He surely won't come back now, at this late stage.","Resolving never to ride a jam-packed train again, I switched to commuting by bicycle."],"t":"～まい","p":"dictionary form ＋ まい (godan verbs) ／masu-form ＋ まい (ichidan, カ変, サ変 verbs)"},"n2-58":{"cat":"Condition / Hypothesis","ex":"\"not necessarily ~ / not always ~.\" Attaches to the plain form. Denies that something is absolutely the case, acknowledging that there are exceptions.","eg":["Expensive things are not necessarily good.","Effort is not always rewarded.","Not all shops with long lines are necessarily delicious."],"t":"～とは限らない","p":"plain form ＋ とは限らない"},"n2-59":{"cat":"Time / Change","ex":"\"triggered by ~ / taking ~ as an opportunity.\" Attaches to a noun. Indicates the event that set off or prompted some change.","eg":["Studying abroad was the trigger that made me start taking an interest in the local food culture.","That incident became the catalyst for reviewing the related regulations.","My job transfer was the opportunity that led me to start learning the local traditional culture."],"t":"～をきっかけに","p":"noun ＋ をきっかけに（して）"},"n2-60":{"cat":"Time / Change","ex":"\"after (a long process of) ~, in the end ...\" Attaches to the ta-form or to a noun with の. Describes a result reached after much effort or trouble, usually an unfavorable or disappointing outcome.","eg":["After agonizing over it endlessly, I ended up deciding not to buy it after all.","After a long discussion, in the end no conclusion was reached.","After getting lost, I ended up taking a taxi to my destination after all."],"t":"～あげく（に）","p":"ta-form ＋ あげく（に）／noun の ＋ あげく（に）"},"n2-61":{"cat":"Time / Change","ex":"\"only after doing ~ (did one finally ...).\" Attaches to the te-form. Emphasizes that one realized or understood something only after experiencing it.","eg":["It was only after being hospitalized that I keenly felt how precious health is.","Only after cooking for myself did I understand how hard my mother had worked.","It was only after living there that I could understand the charm of that town."],"t":"～てはじめて","p":"te-form ＋ はじめて"},"n2-62":{"cat":"Degree / Emphasis","ex":"\"it's best to ~ / nothing beats ~-ing.\" Attaches to the dictionary form or the nai-form. Indicates that doing so is the most desirable or ideal course of action.","eg":["For your health, nothing beats going to bed early and getting up early.","Just in case, you can't have too many preparations.","When going out in midsummer, it's best to have a parasol with you."],"t":"～に越したことはない","p":"dictionary form／nai-form ＋ に越したことはない"},"n2-63":{"cat":"Degree / Emphasis","ex":"\"there is something ~ about it / it truly has a ~ quality.\" Attaches to the plain form. Expresses a deep, felt impression the speaker senses in something.","eg":["There is something captivating about his performance.","There is something somehow nostalgic about this old photograph.","There is something about local shopping streets that warms the heart."],"t":"～ものがある","p":"plain form ＋ ものがある"},"n2-64":{"cat":"Scope / Limitation","ex":"\"without ~ / leaving out ~ / omitting ~.\" Attaches to a noun. Indicates the exclusion of a certain element; use 「ぬきの」 before a noun.","eg":["Joking aside, let's discuss this seriously.","I went to work without breakfast.","Joking aside, this summer's intense heat is extraordinary."],"t":"～ぬきで・～ぬきに・～ぬきの","p":"noun ＋ ぬきで／ぬきに／ぬきの ＋ noun"},"n2-65":{"cat":"Other","ex":"\"do ~ completely / manage to finish ~ (or not).\" Attaches to the verb stem (masu-form minus ます). Indicates thorough completion of an action; 「きれる」 means one can finish it, and 「きれない」 means one cannot finish it.","eg":["I ran the full marathon all the way to the end.","An amount came out that was more than one person could finish eating.","When I finished running the whole 42 kilometers, tears came to my eyes naturally."],"t":"～きる・～きれる・～きれない","p":"masu-form (drop ます) ＋ きる／きれる／きれない"},"n2-66":{"cat":"Time / Change","ex":"\"prior to ~ / before ~.\" Attaches to a noun. Used in formal settings to indicate preparation or notice given before an event takes place.","eg":["Prior to the opening, the organizer gave a greeting.","Prior to the construction, an information session for local residents was held.","Prior to the press conference, only the parties involved held a preliminary meeting."],"t":"～に先立って・に先立ち","p":"noun ＋ に先立って／に先立ち"},"n2-67":{"cat":"Degree / Emphasis","ex":"\"So ~ that one can't stand it.\" Expresses an intense feeling or emotion that cannot be suppressed. Attach 「たまらない」「ならない」「しょうがない」 to the te-form (for 「ならない」, spontaneous verbs like 「思われる」 are also common). More written and formal than the N3 equivalents.","eg":["I'm overjoyed to hear that I passed.","I can't help thinking about my hometown.","My toothache bothers me so much I can't stand it.","After days of overtime I'm unbearably sleepy, but I have to make the deadline."],"t":"～てたまらない・～てならない・～てしょうがない","p":"te-form ＋ たまらない／ならない／しょうがない"}};
const N1_EN = {"n1-1":{"cat":"Limitation / Emphasis","ex":"\"When it comes to ~ (it even reaches the point of…).\" Cites an extreme example to emphasize a point, often the worst or most striking case. Attaches to a noun.","eg":["He's bad at math; when it comes to fractions he's at an elementary-school level.","Going out in midsummer — walking around in the daytime is practically torture."],"t":"～に至っては","p":"noun ＋に至っては"},"n1-2":{"cat":"Limitation / Emphasis","ex":"\"By means of ~\" or \"as of / effective ~.\" Indicates a means/method, or a time limit/deadline. A formal, written expression. Attaches to a noun.","eg":["Applications close as of today.","We will handle it with sincerity.","This project is scheduled to end as of March next year."],"t":"～をもって","p":"noun ＋をもって"},"n1-3":{"cat":"Limitation / Emphasis","ex":"\"Undaunted by ~\" or \"without letting ~ get in the way.\" Emphasizes bravely facing hardship or difficulty. Attaches to a noun.","eg":["Undaunted by her illness, she completed a full marathon.","Undaunted by the intense heat, the players saw the match through to the end."],"t":"～をものともせず","p":"noun ＋をものともせず"},"n1-4":{"cat":"Limitation / Emphasis","ex":"\"Not even a single ~.\" Combines 「一」 plus a counter to emphasize that not even the smallest amount is allowed or possible. Always ends in a negative.","eg":["With the time remaining, I don't want to waste even a single second.","For deals below cost, we won't discount even a single yen.","Not even a single medical error can be tolerated."],"t":"～たりとも…ない","p":"（one ＋ counter）＋たりとも…ない"},"n1-5":{"cat":"Limitation / Emphasis","ex":"\"Even if it is ~\" or \"no matter ~.\" States that the conclusion holds regardless of the case; often paired with 「たとえ」 or 「どんな」. Attaches to a noun.","eg":["Even the company president cannot rise above the law.","No matter the reason, violence cannot be justified.","Even a veteran must not forget their original resolve."],"t":"～であれ","p":"noun ＋であれ"},"n1-6":{"cat":"Limitation / Emphasis","ex":"\"If it's for ~ / if it's a matter of ~.\" Indicates that for a certain purpose or person, one will spare no effort. Attaches to a noun or plain form.","eg":["If it's for their children, parents won't mind any hardship.","If it's a request from a close friend, I can't very well refuse."],"t":"～とあれば","p":"noun／plain form ＋とあれば"},"n1-7":{"cat":"Limitation / Emphasis","ex":"\"There is no one/nothing but ~.\" Emphasizes uniqueness — no other option exists. Attaches to a noun and ends in a negative (often 「ほかにない／ほかにいない」).","eg":["There's no one but him who can be entrusted with this task.","There's no one but the local residents who can protect this town's scenery."],"t":"～をおいて","p":"noun ＋をおいて～ない"},"n1-8":{"cat":"Limitation / Emphasis","ex":"\"Unique to ~ / that only ~ can offer.\" Emphasizes a distinctive quality found only in the thing mentioned. 「ならではの」 modifies a following noun. Attaches to a noun.","eg":["It has a warmth that only handmade things have.","I got to try a dish made with ingredients you can only find locally."],"t":"～ならでは","p":"noun ＋ならでは（の）"},"n1-9":{"cat":"Limitation / Emphasis","ex":"\"Let alone ~, even….\" The first item is obviously out of the question, and even the lesser, easier second item is also the case. Attaches to a noun, often paired with 「さえ」「も」.","eg":["Let alone kanji, I can't even read hiragana yet.","Let alone traveling abroad, I've never even left this prefecture."],"t":"～はおろか","p":"noun ＋はおろか"},"n1-10":{"cat":"Limitation / Emphasis","ex":"\"Even if not ~, at least….\" Steps back to state a minimum expectation when the fuller goal can't be met. Attaches to the nai-form.","eg":["Even if I can't get a perfect score, I at least want a passing grade.","Even if I can't speak like a native, I at least want to manage everyday conversation."],"t":"～ないまでも","p":"nai-form ＋までも"},"n1-11":{"cat":"Limitation / Emphasis","ex":"\"If it were ~, that would be one thing, but….\" The first case would be acceptable/tolerable, but the actual (latter) case goes too far. Attaches to a noun or plain form.","eg":["If it were a joke, fine — but are you saying this seriously?","Being five minutes late is one thing, but being an hour late is unacceptable.","A small mistake would be one thing, but a failure on the scale of harming a client can't be overlooked."],"t":"～ならまだしも","p":"noun／plain form ＋ならまだしも"},"n1-12":{"cat":"Limitation / Emphasis","ex":"\"There may be ~, but certainly not….\" Concedes that the first thing exists while strongly negating the latter. A written, literary expression. Attaches to a noun.","eg":["His actions may draw criticism, but almost no voices of praise are heard.","The local festival may be plain, but there's no sign of it dying out."],"t":"～こそあれ","p":"noun ＋こそあれ"},"n1-13":{"cat":"Limitation / Emphasis","ex":"\"I'll just ~ (and that's all)\" or \"it's nothing more than ~.\" Expresses that the worst case is no big deal — one will simply do the stated thing. Attaches to the dictionary form.","eg":["If it doesn't work out, I'll just start over — that's all.","If the trains stop, I'll just walk home, that's all."],"t":"～まで（のこと）だ","p":"dictionary form ＋まで（のこと）だ"},"n1-14":{"cat":"Time / Change","ex":"\"As soon as / the moment ~.\" Right after the first action is completed, an often unexpected event follows immediately. Attaches to the dictionary form.","eg":["The moment he reached the entryway, he collapsed onto the sofa.","The moment I stepped out of the ticket gate, a stranger asked me for directions."],"t":"～なり","p":"dictionary form ＋なり"},"n1-15":{"cat":"Time / Change","ex":"\"No sooner than ~ / the instant ~.\" Two events occur almost simultaneously, emphasizing how quickly the second follows. Attaches to the dictionary form.","eg":["No sooner had the bell rung than the children dashed out of the classroom.","No sooner did the new product go on sale than it vanished from the shelves."],"t":"～が早いか","p":"dictionary form ＋が早いか"},"n1-16":{"cat":"Time / Change","ex":"\"As soon as ~.\" The two actions happen almost at the same time. A written expression. Attaches to the dictionary form.","eg":["The instant he woke up, he grabbed his smartphone.","The moment the announcement for the last train sounded, the passengers all rushed to the platform."],"t":"～や否や","p":"dictionary form ＋や否や"},"n1-17":{"cat":"Time / Change","ex":"\"No sooner ~ than (it happens again).\" Right after doing something, it reverts to its previous state; carries a sense of frustration or futility, and typically describes a repeated situation. Attaches to the dictionary form or ta-form.","eg":["No sooner do I tidy up than the kids mess it up again.","No sooner am I taught something than I forget it.","No sooner do I wipe the sign than dust settles on it again."],"t":"～そばから","p":"dictionary form／ta-form ＋そばから"},"n1-18":{"cat":"Time / Change","ex":"\"To reach the point of ~ / to end up as ~.\" Indicates that a situation develops all the way to a certain stage or outcome. Attaches to a noun or the dictionary form.","eg":["The problem grew serious and finally reached the point of a lawsuit.","Years of effort bore fruit, and he rose to become CEO."],"t":"～に至る","p":"noun／dictionary form ＋に至る"},"n1-19":{"cat":"Time / Change","ex":"\"All the way up to / down to ~ (everything included).\" Emphasizes a wide range, covering everything from one end to the other. Attaches to a noun.","eg":["It's an event everyone can enjoy, from children all the way to the elderly.","From planning the project all the way through to execution, she handled it single-handedly."],"t":"～に至るまで","p":"noun ＋に至るまで"},"n1-20":{"cat":"Time / Change","ex":"\"After going through / undergoing ~.\" Indicates a result reached after passing through a certain process or stage. A written expression. Attaches to a noun.","eg":["After years of negotiations, the merger of the two companies was realized.","After going through postwar reconstruction, the town regained a new appearance."],"t":"～を経て","p":"noun ＋を経て"},"n1-21":{"cat":"Cause / Reason","ex":"\"In order to ~ / for the sake of ~.\" An archaic, literary expression of purpose. Drop 「ない」 from the nai-form and add 「んがため（に）」 (e.g., 守る→守らんがため); note that 「する」 becomes 「せんがため」.","eg":["In order to win the tournament, he endured grueling practice every day.","In order to protect his family, he took on even dangerous work."],"t":"～んがため（に）","p":"nai-form (drop ない) ＋んがため（に）"},"n1-22":{"cat":"Cause / Reason","ex":"\"in order to~\". A formal, written-style expression of purpose. More formal than 「ために」. Attaches to the dictionary form (note: 「する」 becomes 「すべく」). Often used with volitional/effortful actions taken to achieve a goal.","eg":["In order to achieve the goal, the entire team worked together.","In order to become a first-rate engineer, he made up his mind to study abroad."],"t":"～べく","p":"dictionary form ＋べく"},"n1-23":{"cat":"Cause / Reason","ex":"\"because of~\", \"owing to~\". An archaic, literary expression of cause or reason. Attaches as 「名詞＋（の）ゆえ（に）」 or 「普通形＋がゆえ（に）」. Common in formal writing and set phrases.","eg":["It was a mistake made out of youth.","Precisely because he is so earnest, he is sometimes criticized instead."],"t":"～ゆえ（に）","p":"noun ＋（の）ゆえ（に）／plain form ＋がゆえ（に）"},"n1-24":{"cat":"Cause / Reason","ex":"\"because it is (a special situation)~, therefore…\". Explains that a particular, notable circumstance leads to a certain result. Attaches to the plain form.","eg":["As it was the first day of the holidays, the airport was extremely crowded.","As it was the day of the fireworks festival, the area around the venue was full of traffic restrictions."],"t":"～とあって","p":"plain form ＋とあって"},"n1-25":{"cat":"Cause / Reason","ex":"\"precisely because~, that is why…\". More literary and more emphatic than 「からこそ」. Attaches to the conditional (ば) form. Stresses that the stated reason is the sole and essential cause.","eg":["It is precisely because I worry about your future that I say such harsh things.","It is precisely because you are healthy that you can take on the things you love."],"t":"～ばこそ","p":"ba-form ＋こそ"},"n1-26":{"cat":"Cause / Reason","ex":"\"since I have already~ (I can't back out for the sake of appearances)\". Because of one's face, position, or a prior commitment, one has no choice but to act a certain way. Attaches to the た-form or 「名詞＋の」.","eg":["Since I have already promised, I can't very well refuse now.","In front of my juniors, I can't allow myself to show weakness."],"t":"～手前","p":"ta-form／noun の ＋手前"},"n1-27":{"cat":"Concession / Contrast","ex":"\"even if I do~, it's no use\". Indicates that even doing the action will not lead to a good result. Attaches to the た-form. Often paired with 「どんなに」「いくら」 and followed by a negative or futile outcome.","eg":["Even if you apologize now, the relationship probably won't go back to how it was.","No matter how much you hurry, you won't make the last flight.","Panicking isn't going to change the result."],"t":"～たところで","p":"ta-form ＋ところで"},"n1-28":{"cat":"Concession / Contrast","ex":"\"no matter what/how~\". Whatever is done, the conclusion stays the same. Attaches to the volitional form (「言おうが／言おうと」, 「暑かろうと」). 「が」 and 「と」 are interchangeable here.","eg":["No matter what the people around me say, I will not bend my convictions.","No matter how hot it is, I never skip my morning run."],"t":"～ようが／～ようと","p":"volitional form ＋が／と"},"n1-29":{"cat":"Concession / Contrast","ex":"\"whether it's~ or~\". Lists two cases and states that the conclusion is the same for both. More formal/written than the N2 form 「にしろ」. Attaches to nouns or plain forms.","eg":["Whether you agree or disagree, you should make your position clear.","Whether by train or by taxi, it takes a long time during rush hour."],"t":"～にせよ…にせよ","p":"noun／plain form ＋にせよ…にせよ"},"n1-30":{"cat":"Concession / Contrast","ex":"\"I thought~, but to my surprise…\". The actual result turns out to be completely contrary to what was expected. Attaches to the plain form.","eg":["I thought I had passed, but it turned out I had misread the number.","I thought it was a simple project, but it was actually extremely complicated."],"t":"～と思いきや","p":"plain form ＋と思いきや"},"n1-31":{"cat":"Concession / Contrast","ex":"\"if only~ (but you didn't)\". Carries a tone of regret or reproach that someone failed to do the obvious better thing. Attaches to the plain form.","eg":["You should have just consulted someone sooner; because you kept quiet, the problem got tangled up.","I should have just checked the map, but in the end I ended up taking a long detour."],"t":"～ものを","p":"plain form ＋ものを"},"n1-32":{"cat":"Concession / Contrast","ex":"\"at a time when (you are/it is)~\". Intrudes upon a state that ought to be continuing; often used when apologizing or expressing gratitude for imposing on someone. Attaches to the plain form (often with い/な-adjectives or nouns).","eg":["Thank you so very much for coming all this way when you are so busy.","I'm terribly sorry to bother you during your break, but I'm calling to confirm something."],"t":"～ところを","p":"plain form ＋ところを"},"n1-33":{"cat":"Concession / Contrast","ex":"\"having said that, but…\", \"that may be true, but…\". More conversational and concrete than the N2 form 「とはいえ」. Concedes the first point, then presents a contrasting reality. Attaches to the plain form.","eg":["Things have become more convenient, but there is no small amount that has been lost, too.","The yen may be strong, but overseas travel still feels expensive."],"t":"～とはいうものの","p":"plain form ＋とはいうものの"},"n1-34":{"cat":"Degree / Comparison","ex":"\"extremely~\", \"~ to the utmost degree\". Emphasizes that the degree is very high. Written style. Attaches to the stem of a な-adjective. 「極まりない」 and 「極まる」 are near-synonyms (both mean 'utterly~'), used mostly with negative-quality adjectives.","eg":["That attitude of his is rude in the extreme.","The extremely dangerous driving led to a serious accident.","The commuter train at rush hour is unpleasant in the extreme."],"t":"～極まりない・～極まる","p":"na-adjective stem ＋極まりない／極まる"},"n1-35":{"cat":"Degree / Comparison","ex":"\"the height of~\", \"extremely~ (a feeling)\". Used mostly on formal occasions to express feelings such as gratitude or shame. Attaches to a noun. Common in set phrases like 「光栄の至り」「若気の至り」.","eg":["To be entrusted with such an important role, I am truly honored beyond words.","It was done in the folly of my youth that I did something so rude.","To be given the chance to give a speech at an international conference, I am deeply honored."],"t":"～の至り","p":"noun ＋の至り"},"n1-36":{"cat":"Degree / Comparison","ex":"\"cannot bear~\", \"unbearably~\". Indicates that an emotion is too strong to endure. Written style. Attaches to a noun (often 感謝 etc.); also seen in the set phrase 「見るに堪えない」 (unbearable to watch).","eg":["I cannot fully express my gratitude for everyone's support.","The scene was so tragic that I could not bear to look at it."],"t":"～に堪えない","p":"noun ＋に堪えない"},"n1-37":{"cat":"Degree / Comparison","ex":"\"cannot help feeling~\", \"cannot suppress~\". A strong emotion that one is unable to control. Written style. Attaches to a noun denoting an emotion (sympathy, anger, sadness, etc.).","eg":["When I think of his circumstances, I cannot help feeling sympathy.","Reading the records of the air raids, I could not suppress my sorrow."],"t":"～を禁じ得ない","p":"noun ＋を禁じ得ない"},"n1-38":{"cat":"Degree / Comparison","ex":"\"it is not hard to~\". Indicates that something can be imagined or understood quite easily. Written style. Attaches to a noun (想像・理解 etc.) or the dictionary form.","eg":["It is not hard to imagine how much hardship he went through.","It is not hard to understand why this project is so highly rated."],"t":"～に難くない","p":"noun ＋に難くない／dictionary form ＋に難くない"},"n1-39":{"cat":"Degree / Comparison","ex":"\"to~ endlessly\", \"to~ from the bottom of one's heart\". Expresses a strong, continuous emotion. Written style. Attaches to the て-form (願って, 期待して, 愛して, etc.).","eg":["I sincerely wish all of you ever greater prosperity.","I have boundless hopes for the success of my juniors."],"t":"～て止まない","p":"te-form ＋やまない（止まない）"},"n1-40":{"cat":"Degree / Comparison","ex":"\"in contrast to~ (with a stark difference)\". Emphasizes a great contrast between two things. Attaches to a noun (「名詞＋にひきかえ」). Often carries an evaluative, comparative tone.","eg":["In contrast to how meticulous my older brother is, my younger brother's room is always a mess.","In contrast to the utterly silent city nights, the nights in the old downtown never lack the sound of people's voices."],"t":"～にひきかえ","p":"noun ＋にひきかえ"},"n1-41":{"cat":"Degree / Comparison","ex":"\"~ beyond words\", \"~ to the extreme\". A colloquial expression emphasizing that the degree is extremely high. Attaches to い- or な-adjectives; the shortened 「ったらない」 is even more casual.","eg":["My joy when I heard the news that I had passed was beyond description.","The sheer bitterness of this town's winter cold is unreal."],"t":"～といったらない・～ったらない","p":"i-adjective・na-adjective ＋といったらない"},"n1-42":{"cat":"Degree / Comparison","ex":"\"~ and ~ alike (everywhere)\". Lists representative parts to imply the whole. Attaches to two nouns (「名詞＋と言わず＋名詞＋と言わず」).","eg":["Hands and feet alike, he was covered all over in mud.","Downtown and suburbs alike, the whole town was wrapped in a festival mood."],"t":"～と言わず～と言わず","p":"noun ＋と言わず＋noun ＋と言わず"},"n1-43":{"cat":"Topic / Evaluation","ex":"\"to think that~!\", \"~, of all things!\". Expresses surprise, unexpectedness, or strong emotion. Attaches to the plain form.","eg":["To think that I would actually pass my first-choice school — it was something I never even dreamed of.","To think that such an unknown little shop would have dishes this fine — it's astonishing."],"t":"～とは","p":"plain form ＋とは"},"n1-44":{"cat":"Topic & Evaluation","ex":"\"Speaking of ~ (really...)\". Attached to a noun to raise it as a topic while expressing affectionate complaint, exasperation, or admiration. Colloquial and often used about people (or things) close to the speaker.","eg":["That kid of mine—goes and forgets to bring the homework again, honestly.","That grandma next door, bless her, is always bringing over homemade pickles."],"t":"～ったら","p":"noun ＋ったら"},"n1-45":{"cat":"Topic & Evaluation","ex":"\"When it comes to ~ / As for ~\". Raises a noun as a topic and then delivers a negative, usually critical or disappointed, evaluation of it.","eg":["When it comes to young people these days, they can't even greet you properly.","As for my boss, every time he goes on a business trip he forgets his promise to bring back a souvenir."],"t":"～ときたら","p":"noun ＋ときたら"},"n1-46":{"cat":"Topic & Evaluation","ex":"\"In (the midst of) ~ / Amid ~\". Indicates being in a particular special situation, circumstance, or environment. Formal, written language.","eg":["Even amid difficult circumstances, he never lost hope.","Amid the pandemic, many companies introduced remote work."],"t":"～にあって","p":"noun ＋にあって"},"n1-47":{"cat":"Topic & Evaluation","ex":"\"Once you reach the level/position of ~\". Indicates that once one attains a certain status, level, or occasion, the situation naturally becomes different (with greater weight or scale).","eg":["Once you become a department head, your responsibilities grow heavier and your discretion wider.","Once Golden Week rolls around, popular theme parks get so crowded they have to limit admissions."],"t":"～ともなると","p":"noun ＋ともなると"},"n1-48":{"cat":"Topic & Evaluation","ex":"\"If/once it becomes ~\". Similar to \"ともなると\", but with a stronger hypothetical, conditional nuance: given a certain status or occasion, such-and-such naturally follows.","eg":["Once you become CEO, even your private life falls under the public eye.","Once it's the local fireworks festival, the whole town instantly takes on a festive mood."],"t":"～ともなれば","p":"noun ＋ ともなれば"},"n1-49":{"cat":"Topic & Evaluation","ex":"\"From somewhere ~ / without really ~ing\". With a question word it expresses an uncertain, unidentifiable source; with a dictionary-form verb it expresses doing an action absent-mindedly, without conscious intent.","eg":["A sweet fragrance came drifting from somewhere.","As I was gazing at the TV without really watching, a town I recognized appeared on screen."],"t":"～ともなく","p":"question word ＋ ともなく／dictionary form ＋ ともなく"},"n1-50":{"cat":"Topic & Evaluation","ex":"\"Can't tell whether it's ~ or ~\". Using \"noun + とも + noun + ともつかない\", it expresses an ambiguous, indeterminate state where two possibilities cannot be distinguished.","eg":["It was an expression you couldn't tell was laughing or crying.","At first I was thrown off by his tone, which I couldn't tell was serious or joking."],"t":"～とも～とも","p":"noun ＋ とも ＋ noun ＋ ともつかない"},"n1-51":{"cat":"Topic & Evaluation","ex":"\"Even going so far as to ~\". Emphasizes going to an excessive or extreme length to achieve a goal, doing something one normally wouldn't.","eg":["There's no need to buy brand-name goods even if it means going into debt.","I even stayed up all night waiting in line and got hold of the limited-edition sweets."],"t":"～てまで","p":"te-form ＋ まで"},"n1-52":{"cat":"Sentence-final & Written Language","ex":"\"That should not be done / unforgivable / unbecoming\". Modifies a following noun to express behavior that is improper or impermissible for someone in a given position. Formal, written language.","eg":["That is a remark unbecoming of an educator.","An outburst impermissible for a public figure was let loose in the assembly."],"t":"～まじき","p":"dictionary form ＋ まじき ＋ noun"},"n1-53":{"cat":"Sentence-final & Written Language","ex":"\"Must not ~ / ~ is forbidden\". An archaic prohibition expression. \"べからず\" ends a sentence; the attributive \"べからざる\" modifies a following noun. Often seen on signs and notices.","eg":["No parking here.","Do not jump into the river."],"t":"～べからず・～べからざる","p":"dictionary form ＋ べからず"},"n1-54":{"cat":"Sentence-final & Written Language","ex":"\"probably ~ / likely ~\". An archaic, literary equivalent of \"い-adjective + だろう\", attached to the い-adjective stem to express conjecture.","eg":["That exam will likely be hard, but if you keep piling up preparation you should be able to get through it.","The outdoors in midsummer is probably hot, but the fervor of the festival is worth seeing at least once."],"t":"～かろう","p":"i-adjective stem ＋ かろう"},"n1-55":{"cat":"Sentence-final & Written Language","ex":"\"one who is a ~ (should...)\". Attached to a noun (often as \"たるもの\") to express the duty or standard that comes with a certain status or position. Formal, written language.","eg":["One who is a leader should always remain calm.","One who is an expert must take responsibility for their own words."],"t":"～たる","p":"noun ＋ たる（もの）"},"n1-56":{"cat":"Sentence-final & Written Language","ex":"\"Without ~, ... is impossible\". Used with a following negative to emphasize that something is indispensable; without it, the outcome cannot be achieved. Formal, written language.","eg":["Without daily effort, success is impossible.","Without the residents' cooperation, the revival of this area would have been impossible."],"t":"～なくして（は）","p":"noun ＋ なくして（は）～ない"},"n1-57":{"cat":"Sentence-final & Written Language","ex":"Attached to a noun with several uses: (1) \"only at/upon (the stage of) ~\", emphasizing that something happens only at a certain point (often an age or time); (2) \"being both ~ and ~ at once\". Formal, written language.","eg":["It was only at fifty that he traveled abroad for the first time.","He is a researcher and at the same time an entrepreneur."],"t":"～にして","p":"noun ＋ にして"},"n1-58":{"cat":"Sentence-final & Written Language","ex":"\"as if to say ~ / with an air of ~\". Attached to a quote or plain-form clause, it describes acting as though one were saying that very thing.","eg":["As if to say \"I've been waiting for this,\" he shot his hand up energetically.","As if to say \"Give it a try,\" the shopkeeper held out his newly created bread."],"t":"～とばかりに","p":"plain form ＋ とばかりに"},"n1-59":{"cat":"Sentence-final & Written Language","ex":"\"There's no need to ~ / it doesn't warrant ~ing\". Attached to a dictionary-form verb to say that doing such a thing is unwarranted or unnecessary. Formal, written language.","eg":["Since it was within expectations, it's nothing to be surprised about.","Just being handed a piece of candy at a first meeting is nothing to get flustered over."],"t":"～には当たらない","p":"dictionary form ＋ には当たらない"},"n1-60":{"cat":"Others","ex":"\"while also ~ / on the occasion of ~\". Attached to a noun to indicate doing one (typically formal) errand while at the same time taking care of another. Formal, written language.","eg":["I called on you to pay my respects and also to express my thanks.","While on a business trip, I also finished making the rounds to greet our business partners."],"t":"～かたがた","p":"noun ＋ かたがた"},"n1-61":{"cat":"Others","ex":"\"while ~ / alongside ~\". Indicates doing something else in addition to one's main occupation or activity. Attaches to a dictionary-form verb or \"noun + の\". Formal, written language.","eg":["While working at a company, I write novels on the weekends.","Alongside serving as a teacher, she is also energetically involved in community volunteer work."],"t":"～かたわら","p":"dictionary form／noun の ＋ かたわら"},"n1-62":{"cat":"Others","ex":"\"while doing ~ / and at the same time ~\". Indicates doing another action in the course of doing one thing. Attaches to a noun or the ます-stem of a verb; more formal than \"ついでに\".","eg":["On my walk, I stopped by the convenience store.","As a bit of exercise, I walked to the next station to commute."],"t":"～がてら","p":"noun／masu-form ＋ がてら"},"n1-63":{"cat":"Others","ex":"\"covered in ~ / smeared all over with ~\". Attached to a noun to express that a surface is covered with something (usually unpleasant, like mud, sweat, blood, or dust).","eg":["I played with the kids until I was covered in mud.","Drenched in sweat, I carried the portable shrine at the festival."],"t":"～まみれ","p":"noun ＋ まみれ"},"n1-64":{"cat":"Others","ex":"\"nothing but ~ / all ~\". Attached to a noun to express that everything is of one and the same kind. Often used for colors, or for a run of things (frequently good things, contrasting with the negative-leaning \"まみれ\").","eg":["Today I went out in an all-black outfit.","This week was one full of nothing but good things—recognition, a promotion, and an award.","The food-crawl trip was nothing but delicious things, and I gained weight."],"t":"～ずくめ","p":"noun ＋ ずくめ"},"n1-65":{"cat":"Others","ex":"\"depends on ~ / hinges on how ~ is\". Attached to a noun (read いかん) to express that a result is entirely determined by a certain condition. Formal, written language.","eg":["This term's performance depends on how hard the team works.","The success or failure of the project hinges on the initial response."],"t":"～如何","p":"noun ＋ 如何（いかん）"},"n1-66":{"cat":"Miscellaneous","ex":"\"Regardless of ~\" / \"No matter what ~ is.\" Whatever the condition may be, the conclusion stays the same. Formal/written language. Formed as 「名詞＋の＋いかんによらず／いかんにかかわらず」, where 「いかん」 means \"how/what\" and the whole set phrase means the outcome is unaffected by that factor.","eg":["Regardless of the reason, being late is not permitted.","Regardless of the weather, the event will be held as scheduled."],"t":"～いかんによらず・いかんにかかわらず","p":"noun の ＋ いかんによらず／いかんにかかわらず"},"n1-67":{"cat":"Miscellaneous","ex":"\"In defiance of ~\" / \"Ignoring ~.\" Acting without regard to the worry, concern, or opposition of those around one. Attached to a noun: 「名詞＋をよそに」.","eg":["Ignoring his family's worries, he set off overseas alone.","In defiance of the opposition around her, she chose the path of starting her own business."],"t":"～をよそに","p":"noun ＋ をよそに"},"n1-68":{"cat":"Miscellaneous","ex":"\"Even with ~ (even using the power/ability of ~), it is still not enough.\" Emphasizes that even the strongest or most capable means falls short. Attached to a noun: 「名詞＋をもってしても」, typically followed by a negative or a statement of difficulty.","eg":["Even with the latest technology, there are problems that cannot be fully solved.","Even for a seasoned veteran with plenty of experience, that case was a tough one."],"t":"～をもってしても","p":"noun ＋ をもってしても"},"n1-69":{"cat":"Miscellaneous","ex":"\"Starting with ~\" / \"With ~ as the starting point.\" Something serves as the trigger from which a series of activities or events unfolds. Attached to a noun: 「名詞＋を皮切りに（して）」.","eg":["Starting with the Tokyo performance, the nationwide tour began.","Starting with the launch of the new product, a series of marketing initiatives was rolled out."],"t":"～を皮切りに","p":"noun ＋ を皮切りに（して）"},"n1-70":{"cat":"Miscellaneous","ex":"\"Cannot fail to ~\" / \"Is bound to ~.\" Something has such powerful force that it inevitably brings about a certain result (often an emotional reaction). Formed from the ない-form minus 「ない」 plus 「ずにはおかない」 (「しない」 becomes 「せずにはおかない」). Often used with causative verbs to mean it will surely make someone feel/do something.","eg":["This movie is bound to move its audience.","This documentary cannot fail to make viewers think deeply."],"t":"～ずにはおかない・ないではおかない","p":"nai-form (drop ない) ＋ ずにはおかない"},"n1-71":{"cat":"Miscellaneous","ex":"\"Cannot get away without ~ing\" / \"Must ~ (or it won't be acceptable).\" Because of social obligation, morality, or the circumstances, one has no choice but to do it. Formed from the ない-form minus 「ない」 plus 「ずにはすまない」 (「しない」 becomes 「せずにはすまない」).","eg":["Now that things have come this far, you surely can't get away without apologizing.","As the person in charge, one cannot get away without giving an explanation."],"t":"～ずにはすまない・ないではすまない","p":"nai-form (drop ない) ＋ ずにはすまない"},"n1-72":{"cat":"Miscellaneous","ex":"\"To be forced to ~\" / \"To have no choice but to ~.\" Due to external factors, one is compelled to do something (usually undesirable). Formal/written language. Attached to a noun: 「名詞＋を余儀なくされる」.","eg":["Due to the typhoon, they were forced to cancel the event.","Due to the redevelopment, the long-established shop was forced to relocate."],"t":"～を余儀なくされる","p":"noun ＋ を余儀なくされる"},"n1-73":{"cat":"Limitation & Emphasis","ex":"\"Only ~\" / \"Nothing but ~.\" Emphasizes that there is just this one thing and nothing else. Formal/written language. Formed as 「ただ＋名詞／辞書形＋のみ」.","eg":["There is nothing to do but move forward.","The only way to get through this situation is simply to persevere and keep going."],"t":"～ただ～のみ","p":"ただ ＋ noun／dictionary form ＋ のみ"},"n1-74":{"cat":"Concession & Contrast","ex":"\"It's not that I can't ~\" / \"I might just ~ (under the right conditions).\" A roundabout way of admitting something is possible. Formed from the ない-form plus 「ものでもない」.","eg":["If the conditions are right, it's not that I couldn't take it on.","If the price can be worked out, it's not as though I'd rule out dining at an upscale restaurant."],"t":"～ないものでもない","p":"nai-form ＋ ものでもない"},"n1-75":{"cat":"Degree & Comparison","ex":"\"To have a tendency to ~\" / \"To be prone to ~.\" Refers to an undesirable inclination. Formal/written language. Formed as 「辞書形＋嫌いがある」 (a noun takes 「の」 before 「嫌いがある」).","eg":["He has a tendency to decide things arbitrarily on his own.","Our boss has a tendency to give too many minute, detailed instructions."],"t":"～嫌いがある","p":"dictionary form ＋ 嫌いがある"},"n1-76":{"cat":"Topic & Evaluation","ex":"\"It's not as if ~ (so there's no need to...).\" Used to rebut someone's behavior or way of thinking by pointing out the situation isn't what would justify it. Formed as 「名詞＋ではあるまいし」 or 「普通形＋のではあるまいし」.","eg":["You're not a child, so stop crying already.","It's not as if this is a client we're dealing with for the first time, so a basic mistake like this is inexcusable."],"t":"～ではあるまいし","p":"noun ＋ ではあるまいし／plain form ＋ のではあるまいし"},"n1-77":{"cat":"Sentence-ending & Written Language","ex":"\"As if about to ~\" / \"All but ~ing.\" An exaggerated expression describing someone on the verge of doing an action (or as good as saying/doing it). Formed from the ない-form minus 「ない」 plus 「んばかりに」 (「する」 becomes 「せんばかりに」).","eg":["She pleaded desperately, as if about to burst into tears.","The shop owner held out his new creation as if to say, \"Please, do try a taste.\""],"t":"～んばかりに","p":"nai-form (drop ない) ＋ んばかりに"},"n1-78":{"cat":"Cause & Reason","ex":"\"There is ... only because there is ~\" / \"~ is what makes ... possible.\" Emphasizes that the first item is the essential prerequisite for the existence of the second. Formed as 「名詞＋あっての＋名詞」.","eg":["A business exists only because there are customers.","It's only with your health that you can take on challenges; if you ruin your body, it all comes to nothing."],"t":"～あっての","p":"noun ＋ あっての"},"n1-79":{"cat":"Miscellaneous","ex":"\"Tend to easily ~\" / \"Be apt to ~ at the slightest thing.\" Indicates a proneness to fall into an undesirable tendency. Used as 「ともすると」 / 「ともすれば」, often paired with 「がち」 or 「やすい」.","eg":["Lately, I tend to slack off all too easily.","Once you get used to convenience, you're apt to forget your sense of gratitude."],"t":"～ともすると・ともすれば","p":"ともすると／ともすれば"},"n1-80":{"cat":"Miscellaneous","ex":"\"Not limited to ~\" / \"Not stopping at ~.\" Something extends beyond a certain scope and continues to spread further. Attached to a noun: 「名詞＋にとどまらず」.","eg":["The damage was not limited to one region; it spread nationwide.","This company's influence does not stop at the domestic market but extends widely overseas as well."],"t":"～にとどまらず","p":"noun ＋ にとどまらず"},"n1-81":{"cat":"Limitation & Emphasis","ex":"\"Even ~\" / \"Not even ~.\" Cites an extreme example for emphasis. More formal/literary than 「さえ」. Attached to a noun: 「名詞＋すら」.","eg":["I don't even know his name.","To not even understand this basic theory is astonishing."],"t":"～すら","p":"noun ＋ すら"},"n1-82":{"cat":"Time & Change","ex":"\"With ~ as the last (time)\" / \"As of ~ (and no longer after).\" Indicates a deadline or cutoff point after which something ends. Attached to a noun: 「名詞＋を限りに」.","eg":["As of today, I'm quitting smoking completely for good.","As of the end of this month, the long-established udon shop will close its doors."],"t":"～を限りに","p":"noun ＋ を限りに"},"n1-83":{"cat":"Miscellaneous","ex":"\"To take on the feel of ~\" / \"To become somewhat like ~.\" Indicates that something is giving off or coming to have a certain atmosphere or quality. Attached to a noun: 「名詞＋めく」 (conjugates as a verb, e.g. 「春めく」).","eg":["All at once it has started to feel like spring.","With the lanterns lined up, the streets have taken on a festival-like atmosphere."],"t":"～めく","p":"noun ＋ めく"},"n1-84":{"cat":"Degree & Comparison","ex":"\"As much as a full ~\" / \"No less than ~.\" Emphasizes how large a quantity or amount is. Attached to a numeral/quantity: 「数量＋からある」 (mass/size), 「からする」 (price/cost), 「からの」 (before a noun).","eg":["He hauled a load weighing a full 100 kilograms all by himself.","The castle keep is a massive structure standing no less than 50 meters tall."],"t":"～からある・～からする・～からの","p":"quantity ＋ からある／からする／からの"},"n1-85":{"cat":"Concession & Contrast","ex":"\"Even if one wants to ~, one cannot ~.\" One wishes to do something but is objectively unable to. Formed as 「意向形＋にも＋可能動詞のない形」 (volitional form + にも + negative potential form of the same verb).","eg":["It was a situation where I couldn't escape even if I wanted to.","Even if I wanted to make a reservation, I can't, because the seats are booked solid for months ahead."],"t":"～ようにも～ない","p":"volitional form ＋ にも ＋ potential verb nai-form"},"n1-86":{"cat":"Sentence-ending & Written Language","ex":"\"Although it is said to be ~, still...\" An archaic-sounding concessive expression. More literary/formal than 「とはいえ」. Formed as 「普通形＋とは言い条（いいじょう）」.","eg":["Although one is a professional, one can still make mistakes.","Although it's called a culinary capital, that doesn't mean every single shop is delicious."],"t":"～とは言い条","p":"plain form ＋ とは言い条（いいじょう）"},"n1-87":{"cat":"Miscellaneous","ex":"\"Whether ~ or ~.\" Lists two opposing i-adjective stems to say that regardless of the degree, the result holds. Formed as 「い形容詞の語幹＋かれ＋（対の）い形容詞の語幹＋かれ」. Common set phrases include 「多かれ少なかれ」 (more or less) and 「遅かれ早かれ」 (sooner or later).","eg":["More or less, everyone carries some stress.","Sooner or later, population decline will surely change the face of the town."],"t":"～かれ～かれ","p":"i-adjective stem ＋ かれ ＋ (another) i-adjective stem ＋ かれ"},"n1-88":{"cat":"Topic & Evaluation","ex":"\"end up in the (bad) situation of ~\". After a chain of unfortunate events, things end up even worse than before. Carries a negative, exasperated tone. Attaches to the dictionary/plain form of a verb.","eg":["Not only was I late, I also forgot something, and in the end I ended up getting scolded by my boss.","I ate too much and ended up feeling sick on the train home."],"t":"～始末だ","p":"plain form (dictionary form) ＋ 始末だ"},"n1-89":{"cat":"Others","ex":"\"without ~ / without doing ~\". Used with a noun to mean an action is (or must not be) done without the thing named. In the 「なしには～ない」 form it means \"without ~, it is impossible / it won't work\".","eg":["You must not use other people's things without permission.","Without a reservation, you can't get into that popular ramen shop."],"t":"～なしに・なしには","p":"noun ＋ なしに／なしには～ない"},"n1-90":{"cat":"Others","ex":"\"under the pretext of ~ / using ~ as an excuse\". One uses some matter as a pretext to do something else that is one's real aim. Attaches to a noun.","eg":["Using the business trip as an excuse, I enjoyed some sightseeing.","Under the pretext of entertaining a client, I got to eat at a high-end restaurant."],"t":"～にかこつけて","p":"noun ＋ にかこつけて"},"n1-91":{"cat":"Limitation & Emphasis","ex":"\"worth ~ing / sufficient to ~\" versus 「に足りない」 \"not worth ~ing\". Attaches to the dictionary form of a verb to express whether something has enough value or merit to justify the action. Formal, written language.","eg":["He is a person worthy of one's complete trust.","That historic castle is a famous site well worth visiting once."],"t":"～に足る・～に足りない","p":"dictionary form ＋ に足る／に足りない"},"n1-92":{"cat":"Degree & Comparison","ex":"\"coupled with ~ / combined with the effect of ~\". Two factors combine to produce an even greater effect. Attaches to a noun.","eg":["Coupled with the perfect weather, the event was a huge success.","Combined with the local warmth and hospitality, the shopping street is becoming even more lively."],"t":"～と相まって","p":"noun ＋ と相まって"},"n1-93":{"cat":"Others","ex":"\"once you ~, that's the end of it\". Once the action is done, there is no going back / it inevitably leads to a bad outcome. Attaches to the past (た) form of a verb.","eg":["Once you confide a secret to that person, it's all over — the rumor spreads in no time.","Once you enter an all-you-can-eat place, that's it — you overeat and can't move."],"t":"～たが最後","p":"ta-form ＋ が最後"}};
